(function(){
 if(!window.JW_CHAPTERS) window.JW_CHAPTERS=[];
 window.JW_CHAPTERS.push({"id":"ch58","num":58,"title":"终章 · 汉室余晖","desc":"终章 · 汉室余晖（原版剧本 R_58.EEX）","map":"assets/maps/map00.png","intro":{"title":"终章 · 汉室余晖","nodes":[{"type":"say","who":"旁白","text":"Ю絞非称Ю絞孤臣之死成都宫殿步兵这家伙是人吗？一个人就杀了我们这么多弟兄…"},{"type":"say","who":"胡渊","text":"不用害怕，这家伙已经是强弩之末了。"},{"type":"say","who":"胡烈","text":"鹞鸱，没有我的命令，不准往前一步！"},{"type":"say","who":"胡渊","text":"这家伙害死我们这么多弟兄，又差点害死您，为什么还要阻止我杀他？"},{"type":"say","who":"胡烈","text":"姜伯约将军，在下安定胡烈，方才小儿有冒犯之处，敬请原谅。"},{"type":"say","who":"胡烈","text":"现在贼首钟会已死，您已经没有继续奋战的必要，何不就此投降？我会向朝廷说是您协助平乱的。"},{"type":"say","who":"胡渊","text":"爹，这岂不是欺君？"},{"type":"say","who":"姜维","text":"看来你还是完全不了解我呀…我从来没有为钟会效忠的意思，他不管是死或活都没有任何差别。"},{"type":"say","who":"胡烈","text":"那您就更不需要再战斗了，放下刀剑，我很期待我们将来的共事。"},{"type":"say","who":"姜维","text":"当钟会死的时候，复兴大汉的计画就已经确定破灭，我也无法继续活下去了。"},{"type":"say","who":"胡烈","text":"这又是何苦呢？您过去也是我们大魏的臣子，现在只是回归而已，不算是叛臣。"},{"type":"say","who":"姜维","text":"要知道，如果让我继续活下去，我会不断想要找机会复国，不停再度背叛你们，这样的人对你们只是威胁而已。"},{"type":"say","who":"胡烈","text":"为什么要这么固执？明明当时您不也投降了诸葛亮？"},{"type":"say","who":"姜维","text":"情况完全不同，当时我没有受大魏的策名，而我效忠的太守直接抛弃了我。"},{"type":"say","who":"姜维","text":"丞相拯救了我并予机会，让我能获得今天的地位。"},{"type":"say","who":"姜维","text":"这个知遇之恩，就算用十生都难以回报。"},{"type":"say","who":"姜维","text":"然而我却让大汉在我眼前灭亡，就算拚尽最后的努力也无力回天。现在只有以一死来表示对丞相的歉意。"},{"type":"say","who":"胡渊","text":"爹！快让我亲手宰了他！"},{"type":"say","who":"胡烈","text":"住手！难道你连一点武人的精神都没有？"},{"type":"say","who":"胡烈","text":"我明白了，安定胡烈在此守护您走上最后一程，希望您一路好走。"},{"type":"say","who":"姜维","text":"丞相，姜维实在是没有脸见您，北伐不但无功，还让大汉落入贼人之手。"},{"type":"say","who":"傅佥","text":"大将军，我们每个人都以您为荣。"},{"type":"say","who":"赵广","text":"待在您帐下是我们一生中最荣耀的事。"},{"type":"say","who":"姜维","text":"为什么？为什么我会看到已死之人？"},{"type":"say","who":"赵云","text":"已经够了，就算现在到这边，面对先帝也可以抬头挺胸。"},{"type":"say","who":"魏延","text":"在绝望时刻永不放弃，你比我这个一怒之下就舍弃一切的匹夫要强太多了。"},{"type":"say","who":"尹赏","text":"伯约，太了不起了，你真的是我们冀城的骄傲。"},{"type":"say","who":"陈祗","text":"没想到最后还是这样的结局，你叫我怎么说你？"},{"type":"say","who":"姜维","text":"赵将军？文长？尹兄？奉宗？"},{"type":"say","who":"诸葛亮","text":"伯约，不需要道歉，亮还没有你这样的勇气，宁愿让自己背负恶名，也要赌上最后的一点机会来复国。"},{"type":"say","who":"姜维","text":"但是我还是失败了…"},{"type":"say","who":"诸葛亮","text":"成败不足以论英雄，我们只是尽自己所能去做而已。"},{"type":"say","who":"姜维","text":"如果大家责怪我的话，或许我还会好受一点…"},{"type":"say","who":"诸葛亮","text":"亮真的没有办法责备一个已经尽力的人。就像先帝也没有责怪亮一样。"},{"type":"say","who":"诸葛亮","text":"放心吧，大汉就算现在灭亡，但是继承大汉精神的人还是在，大汉的立国根基可不是这么容易被消灭的。"},{"type":"say","who":"姜维","text":"香…果然最后的最后，是你来迎接我…"},{"type":"say","who":"尹香","text":"你已经尽力了，不要再责怪自己。"},{"type":"say","who":"尹香","text":"当初我对你的三个请求，其实只是要你坚强地活下去而已。"},{"type":"say","who":"尹香","text":"什么功成名就，其实我一点也不在乎。"},{"type":"say","who":"尹香","text":"你所做的远超过我的请求，这四十年你也名满三国，以一己之力撑起蜀国。"},{"type":"say","who":"尹香","text":"所以真的够了，不需要再让自己这么辛苦了。"},{"type":"say","who":"姜维","text":"真的可以休息了吗？"},{"type":"say","who":"尹香","text":"走吧…卸下一切的重担…到这里来和大家一起相聚吧。"},{"type":"say","who":"姜维","text":"各位，请原谅我先走一步，希望大家能平安无事…"},{"type":"say","who":"胡渊","text":"该死！我生不能杀其人，死也要戮其尸！"},{"type":"say","who":"胡烈","text":"鹞鸱，住手！"},{"type":"say","who":"胡渊","text":"爹！"},{"type":"say","who":"胡烈","text":"他也是一世豪杰，好好安葬吧。公元二六四年正月十八日，姜维苦心策画的复国大计宣告失败，他本人被蜂拥而上的乱军所害，年六十三岁。据《三国志　姜维传》的注引《世语》记载，姜维死后腹部被剖开，发现他的胆跟斗一样大。姜维死后，后世对他的评价两极化，有认为他忠勇忘身，虽败不失为名将。也有认为他穷兵黩武，导致蜀汉灭亡。曾经和姜维共事过的郤正的看法可供参考：“凡人之谈，常誉成毁败，扶高抑下，咸以姜维投厝无所，身死宗灭，以是贬削，不复料擿，异乎春秋褒贬之义矣。”最后的袁氏成都宫门"},{"type":"say","who":"王买","text":"这家伙应该可以靠近了吧，已经好一阵子一动也不动。步兵将军要靠近请自己靠近。"},{"type":"say","who":"王买","text":"夏侯咸那些家伙，把最难打又没什么价值留给我们，自己跑去打钟会。步兵您明明知道，还一直让弟兄们去送死。"},{"type":"say","who":"袁綝","text":"看来我真的没力了，这些人要是再涌上来，也就只有乖乖等死。"},{"type":"say","who":"袁綝","text":"死前就来看这封信吧…袁綝吾儿：在袁家最困顿的时候让你降生，为父感到非常抱歉。本来想要教训那背叛者曹瞒，却没想曹瞒用尽诡诈手法，骗得许攸、张郃等人背叛，使为父不幸在官渡惨败。数万大军尽数葬送。接著又在仓亭败给那狡猾曹瞒，一时间竟使那竖子成名。现虽为父坐镇河北，曹瞒不敢北上，但冀州各郡县纷起叛乱，为父光稳定河北就已心力交瘁，近日更感到力不从心，深知已不久于人世。你却在此时降生，让为父感到悲怆莫名。为父深知显思（袁谭）和显甫（袁尚）两人水火不容，家臣又分成两派相互攻讦。只怕日后两人相争，你会被正室刘夫人或其他兄弟所害，所以将你送到汝南袁家本家避祸。若日后河北纷乱，你在汝南还可以避开这灾祸，免于骨肉相残之争。就算曹瞒侥幸入侵河北，你也不至受害。我相信曹瞒这家伙不管再无耻，应该也不至于敢把屠刀对向汝南的袁家本家，这是连董卓都不敢为之恶行。日后长大，你可以不用挂念这未谋面的父亲，但请你要记得，要时时以四世三公的袁家为荣，你流的血是最宝贵的。"},{"type":"say","who":"袁綝","text":"我终于明白义父为什么不杀我，还坚持让我姓袁的道理。"},{"type":"say","who":"袁綝","text":"一个惨杀义父挚友的冷血动物，却在这时表现出人性来，真叫人不知道怎么反应。"},{"type":"say","who":"袁綝","text":"也罢，到那里再好好揍你一顿吧。步兵贼首钟会和姜维都已经伏法，我军已经平乱成功。"},{"type":"say","who":"袁綝","text":"是吗？伯约也死了？"},{"type":"say","who":"王买","text":"那还等什么，把眼前这家伙也一起干掉，为那些死难的弟兄们报仇。步兵"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"scene","bg":"default","name":"庞会的复仇"},{"type":"say","who":"旁白","text":"成都关家"},{"type":"say","who":"庞会","text":"整个关家就只剩下你一个人了，不害怕吗？"},{"type":"say","who":"关彝","text":"我又有什么好怕的？只恨我没有能力守护家人，让他们命丧你这奸贼之手。"},{"type":"say","who":"庞会","text":"奸贼？！关羽斩杀我父亲，我为父报仇乃是天经地义。"},{"type":"say","who":"关彝","text":"战场上交锋造成的死伤，也想要算到我祖父身上来？"},{"type":"say","who":"庞会","text":"哼，那又如何？我生存的目的就是复仇，为了复仇，我不惜对司马家，甚至钟会卑躬屈膝，就是在等今天的机会。"},{"type":"say","who":"关彝","text":"哈哈哈，我明白了。你只不过是个悲哀的胆小鬼而已。"},{"type":"say","who":"关彝","text":"父亲被称为忠臣，你无力去对抗篡国之贼，只好用报父仇这种藉口掩饰自己的无能。"},{"type":"say","who":"庞会","text":"住口！"},{"type":"say","who":"关彝","text":"可悲呀，当年庞德大喊：“我宁做国家的鬼，也不做贼将。”自己的儿子却当了贼将…"},{"type":"say","who":"庞会","text":"你们通通给我去死吧！"},{"type":"say","who":"关彝","text":"（三叔，至少关家还有你逃过一劫，关家以后的传承就交给你了…）刘禅的悔恨成都刘禅住处"},{"type":"say","who":"刘禅","text":"右车骑将军，外面的情况到底怎么样？"},{"type":"say","who":"廖化","text":"宫殿那边情况不明，但是外面的乱军到处烧杀掳掠，太仆蒋显和太子都已经罹难了。"},{"type":"say","who":"刘禅","text":"什么？！太子遇害了？"},{"type":"say","who":"廖化","text":"所以请陛下千万不可以踏出门一步。"},{"type":"say","who":"刘禅","text":"看见自己的儿子被杀，却只能在这里当缩头乌龟，朕还真是窝囊。"},{"type":"say","who":"张皇后","text":"就算已经亡国，您也还是一国之君，要学会保护自己。"},{"type":"say","who":"张皇后","text":"现在出去逞匹夫之勇又有什么用？"},{"type":"say","who":"张皇后","text":"右车骑将军，这里就交给我，要挡住这些乱军一时半刻还没有问题。"},{"type":"say","who":"张皇后","text":"我希望你现在去找贼军的主将，不管是卫瓘或是胡烈，要他们带人来保护皇上。"},{"type":"say","who":"廖化","text":"我明白了，那么圣上就交给皇后您了。"},{"type":"say","who":"刘禅","text":"（朕从小就被赵叔叔保护，长大以后被相父保护，没想到现在年近六旬还是继续被人保护…）"},{"type":"say","who":"刘禅","text":"（朕曾经也想要振作，想要保护别人，却总是什么也办不到。若是朕能够再振作一点，又怎么会变成这样的局面？）"},{"type":"say","who":"张皇后","text":"皇上，已经过去的事情就算了，现在您还是蜀地九十四万军民的国君，打起精神来吧。"},{"type":"say","who":"张皇后","text":"不用担心，就算是接下来要到洛阳，梓童也会陪您到底，就如同我老爹如何陪先帝那样。"},{"type":"say","who":"刘禅","text":"皇后…生存的意义成都城内"},{"type":"say","who":"句扶","text":"你想要做什么？你都已经多活这么多年了，为什么要在这个关头放弃？"},{"type":"say","who":"宁随","text":"已经没有希望了，当这些乱兵冲进来的一刻，我们大汉已经没有复国的可能。不如一死以谢丞相。"},{"type":"say","who":"宁随","text":"而且你也该明白，伯约在这种情况下是不可能生还的。"},{"type":"say","who":"句扶","text":"难道你就这样放弃了？当初皇上投降的时候，大将他宁可放弃自己的名誉也要拚那一丁点复国的希望，而你呢？"},{"type":"say","who":"句扶","text":"你是聪明人，又曾经是丞相看好的接班人，为什么在这时候却蠢成这样？"},{"type":"say","who":"宁随","text":"事到如今，又能做什么？"},{"type":"say","who":"句扶","text":"难道你认为这样就完了？天下还有很多地方不是司马家的，事情并没有结束！"},{"type":"say","who":"宁随","text":"对呀…"},{"type":"say","who":"句扶","text":"我们还是有复国的希望，哪怕是等到十年、二十年以后，只要我们把那希望的种子给洒下去，终有开花结果的一天。"},{"type":"say","who":"宁随","text":"到最后，我的智慧还远不如你，亏我还自诩是常败军的智囊。"},{"type":"say","who":"宁随","text":"你说的没错，天下还没有被司马家完全拿去，我们还是有翻盘的机会。"},{"type":"say","who":"宁随","text":"东有东吴，北有外族，南有南中，这些地方都不是司马家可以掌握的。"},{"type":"say","who":"句扶","text":"果然聪明的人还是不一样，其实我刚才还完全没有想到这些…"},{"type":"say","who":"杨兰","text":"总算看到你们了，现在局势很混乱，快点跟我们走。"},{"type":"say","who":"句扶","text":"杨姑娘？诸葛姑娘？你们怎么会在这里？"},{"type":"say","who":"诸葛果","text":"详细的情形等稍后再说…请问主公呢？"},{"type":"say","who":"宁随","text":"他正在别的地方，似乎已经和张翼将军一起逃出去了。"},{"type":"say","who":"句扶","text":"（你为什么要骗她们？）"},{"type":"say","who":"宁随","text":"（我不想扼杀她们的心。）"},{"type":"say","who":"杨兰","text":"这样…那就快走吧…"},{"type":"say","who":"诸葛果","text":"………姜维之妻成都城门"},{"type":"say","who":"杨兰","text":"听我说，如果再继续这样下去，恐怕我们根本没有机会逃出成都。"},{"type":"say","who":"杨兰","text":"不如让我留下来抵挡敌军，这样至少你们三人可以脱身。"},{"type":"say","who":"句扶","text":"虽然你很厉害，但不代表可以对付这么多敌兵呀…"},{"type":"say","who":"杨兰","text":"我可是一骑当千，三国无双，这点敌兵"},{"type":"say","who":"旁白","text":"▶ 不需要为我担心。"},{"type":"say","who":"宁随","text":"你要骗骗句扶或许还可以，但是要骗我或是诸葛姑娘就不行了。"},{"type":"say","who":"诸葛果","text":"想要宣称自己是主公的妻子，这样贼兵就会忙著杀你而让我们逃走…"},{"type":"say","who":"句扶","text":"开什么玩笑呀！我怎么可能让你做这种事情？"},{"type":"say","who":"杨兰","text":"还有其他办法吗？连你旁边两个聪明人都想不出来了，你又想得到？"},{"type":"say","who":"句扶","text":"大不了和贼军拚了！你舍弃自己故乡，和我们同甘共苦这么多年，现在怎么能让你牺牲？"},{"type":"say","who":"杨兰","text":"我也不想就这样死呀！但是如果只牺牲我一个人就可以换得大家的生还，我又能做什么选择？"},{"type":"say","who":"诸葛果","text":"这…让果来代替呢？"},{"type":"say","who":"杨兰","text":"只有你才认识五斗米道的人吧。你死了，谁又可以带路？"},{"type":"say","who":"杨兰","text":"还有，平常你总是称我为主母，现在就让我来命令你，赶快带走这些人！"},{"type":"say","who":"诸葛果","text":"………"},{"type":"say","who":"杨兰","text":"难道你还想违抗命令？"},{"type":"say","who":"诸葛果","text":"我知道了…"},{"type":"say","who":"宁随","text":"其实应该让我这个老人先死的，本来早在三十多年前，我就该被丞相处死。"},{"type":"say","who":"杨兰","text":"人家可对你这个老头没兴趣呢！"},{"type":"say","who":"杨兰","text":"快走吧…这些年来，和你们相处，真的很快乐…我是说真的…"},{"type":"say","who":"诸葛果","text":"主母，永别了。"},{"type":"say","who":"杨兰","text":"是呀，万一姜维逃出来的时候，请代替我揍他，知道吗？"},{"type":"say","who":"诸葛果","text":"我明白了。"},{"type":"say","who":"杨兰","text":"其实我只是想要这么一次而已，就算是假的也好。"},{"type":"say","who":"杨兰","text":"至少在这一刻，我和那尹香可是平起平坐的。士兵前面挡著的这个女人是谁？"},{"type":"say","who":"杨兰","text":"我是大汉大将军姜维的正妻杨兰。士兵是那个把我们主帅害得很惨的姜维的妻子？士兵宰了她！士兵我要活剥她的皮！"},{"type":"say","who":"杨兰","text":"看来，这些人似乎不会让我好死呢，呵呵呵…"},{"type":"say","who":"杨兰","text":"（后悔吗？不，我不后悔，这三十多年真的很快乐。）"},{"type":"say","who":"杨兰","text":"（有可以思慕的人，有患难与共的伙伴，还有遥不可及的奋斗目标，这样的人生又还有什么要求的？）"},{"type":"say","who":"杨兰","text":"（对了，为什么我到现在才想起来，当时汉人屠杀我部落时，那个背著同伴放走我的人真的好像姜维…）姜维遇害的同时，他的妻子也同样被乱兵所杀。但是却没有人知道，姜维这个妻子的真实身分…成都西山五斗米道"},{"type":"say","who":"武官","text":"快点把人交出来！别以为我没看见你放那些蜀将进山里。"},{"type":"say","who":"武官","text":"贼首姜维和他妻子都已经死在我们手上，我们要斩草除根，永绝后患。"},{"type":"say","who":"范长生","text":"你知道这里是哪里？"},{"type":"say","who":"旁白","text":"▶ 是谁的地盘？"},{"type":"say","who":"范长生","text":"我们五斗米道在这里立足了数十年，没有人敢踏进这座山里一步，难道你们有这个勇气踏进来？"},{"type":"say","who":"武官","text":"还不是妖道！弟兄们，咱们冲进去！步兵我也是五斗米道的鬼卒…步兵我爹过去也是汉中五斗米道的鬼卒…"},{"type":"say","who":"范长生","text":"我们蜀地五斗米道，光信众就超过十万，只是我们不喜欢干涉世事。"},{"type":"say","who":"范长生","text":"如果你们不踏进来，我也不会去干涉你们外面的事情，好好想清楚吧。"},{"type":"say","who":"武官","text":"（五斗米道好像真的不好惹。算了，反正对付五斗米道也不是我这种下级士官能做的事。）"},{"type":"say","who":"武官","text":"哼！撤退！"},{"type":"say","who":"范长生","text":"（呼…为了保护这些蜀将，居然破例和外界冲突了。）"},{"type":"say","who":"范长生","text":"（不过，我们五斗米道也很难在这乱世中独善其身，或许有一天得加入这样的混战吧。）"},{"type":"say","who":"范长生","text":"刚才的话，你都听到了？姜维已经不在人世了…"},{"type":"say","who":"诸葛果","text":"主公本来就不可能逃过这一劫，他为了取得钟会信任，一直都待在他身边。"},{"type":"say","who":"范长生","text":"我也不是不知道你对姜维的感情，这个时候你实在应该大哭一场。"},{"type":"say","who":"诸葛果","text":"笑也一生…"},{"type":"say","who":"范长生","text":"别对我说这种话，你难道过去都这样压抑自己的感情？现在你也该学会放下这一切，好好做自己吧。"},{"type":"say","who":"诸葛果","text":"呜…呜…哇哇哇哇哇…"},{"type":"say","who":"范长生","text":"（连这样坚强的女子都为他哭泣，到底姜维是何方神圣？只可惜我没有机会和他见面了。）曹魏军军营暗杀之谋"},{"type":"say","who":"卫瓘","text":"（钟会伏诛虽然是好事，但是邓艾这边可就…）"},{"type":"say","who":"卫瓘","text":"（说什么我也和钟会一起陷害过邓艾，要是他回复自由身，我可有数不尽的麻烦。）"},{"type":"say","who":"田续","text":"请问监军找末将有何事？"},{"type":"say","who":"卫瓘","text":"想不想要报仇？"},{"type":"say","who":"田续","text":"末将不是很明白您的意思。"},{"type":"say","who":"卫瓘","text":"我听说邓艾在江油说要诛杀你，还让你混在步兵的队伍中羞辱你。"},{"type":"say","who":"卫瓘","text":"现在有个机会可以让你报复江油那次的羞辱。"},{"type":"say","who":"田续","text":"末将该怎么做？"},{"type":"say","who":"卫瓘","text":"钟会被杀，现在邓艾的部众认为邓艾一定可以沉冤得雪，所以跑去接他了。"},{"type":"say","who":"卫瓘","text":"单靠师纂的部队，恐怕会让邓艾逃脱。"},{"type":"say","who":"田续","text":"所以大人要我去支援，继续押送邓艾？"},{"type":"say","who":"卫瓘","text":"邓艾部众一定会有激烈抵抗，有抵抗就会有死伤，而刀剑又不长眼…"},{"type":"say","who":"田续","text":"我明白了，末将一定照办！"},{"type":"say","who":"卫瓘","text":"（邓艾，你也别怨我，想要你死的人实在太多了，说不定连相国他也不希望你活著呀。）绵竹附近重获自由步兵快点放了太尉！"},{"type":"say","who":"师纂","text":"你们这些人是想造反了吗？难道不知道我是益州刺史，是奉朝廷之命押邓艾回洛阳的人？"},{"type":"say","who":"邓艾","text":"哈哈哈哈哈…看来是钟会那个狗贼造反被杀了，反贼终究是没有好下场的。步兵不错，反贼钟会已经伏诛，如此更可证明太尉的清白，所以我们要把他带回成都。"},{"type":"say","who":"师纂","text":"胡说！我什么命令都没有接到。"},{"type":"say","who":"邓忠","text":"你这家伙，快点认命放了我们吧！"},{"type":"say","who":"邓艾","text":"不用了，反正这家伙和我们陇西军没有什么渊源，加上平日对士卒又刻薄寡恩，士兵根本不会听他的。"},{"type":"say","who":"邓艾","text":"我们就在这里看戏就好了，看一个愚人"},{"type":"say","who":"旁白","text":"▶ 是怎么样死的。"},{"type":"say","who":"邓艾","text":"裴松之引《魏晋世语》说，师纂被愤怒的陇西军杀害，因为他对人性急又少恩惠，死时据说身上没有一处皮肤是完好的。绵竹附近邓艾之死"},{"type":"say","who":"邓艾","text":"田续，这是什么意思？"},{"type":"say","who":"田续","text":"什么意思？你应该比我还清楚。"},{"type":"say","who":"邓艾","text":"卫瓘这家伙一定是怕我回成都之后向他报复，所以派你在这个地方阻截我。"},{"type":"say","who":"田续","text":"我奉监军之命，特来拿邓艾父子归案，如果有抵抗者，定斩不赦。"},{"type":"say","who":"邓忠","text":"爹，事到如今，就算跟他回去也难逃一死。"},{"type":"say","who":"邓艾","text":"没错，卫瓘那家伙不会放过我的…等一下…事情不是这样的…"},{"type":"say","who":"邓忠","text":"什么？！"},{"type":"say","who":"邓艾","text":"如果相国他不想我死，他绝对会保护我，至少会让卫瓘这种谨慎小心的人知道杀我的后果。"},{"type":"say","who":"邓艾","text":"然而卫瓘却如此有恃无恐，看来真正想要我死的可不见得只有卫瓘…"},{"type":"say","who":"邓忠","text":"爹，司马家的天下有一半是您打下来的，为什么他要这样对您？"},{"type":"say","who":"邓艾","text":"狡兔死，良狗亨；高鸟尽，良弓藏；敌国破，谋臣亡。"},{"type":"say","who":"邓艾","text":"我明明知道文种、淮阴的下场，却还是走上和他们相同的道路。"},{"type":"say","who":"邓忠","text":"爹，这时候就该带著笑容，用手上的刀剑和敌人做最后一搏。"},{"type":"say","who":"邓忠","text":"爹，希望我们来生还能当父子。步兵我们陇西部队也希望来生能当你们部属。"},{"type":"say","who":"邓艾","text":"有你们这样的部下，我邓艾可是虽死而无憾！重获自由的邓艾父子在绵竹被追上来的田续斩杀。不久后，司马昭也把邓艾留在洛阳的其他儿子全数斩杀，并且把邓艾的妻子和孙儿都流放到西城。其后朝中屡有为邓艾平反之议，然而却直到公元二七三年，司马炎才应段灼、樊建等人所言，正式为邓艾平反。将其孙邓朗拔擢为郎中。邓艾建立旷世奇功，却蒙受如此大冤，而后世也没有多少人为他抱屈，令人不胜唏嘘。曹魏军军营杜预之怒"},{"type":"say","who":"卫瓘","text":"我听说您在大家面前，批评我的行为。我也知道错了，请接受我的道歉。"},{"type":"say","who":"杜预","text":"哼！你曾祖卫暠是个令人尊敬的儒学大家，你父亲卫觊也声誉卓著。"},{"type":"say","who":"杜预","text":"结果你既没有品德，又不能用正直的作为作部下表率，用公权力满足私欲，你简直是丢你河东卫家的脸！"},{"type":"say","who":"卫瓘","text":"唉…我也是不得已的，要知道想他死的可不只有我而已呀。"},{"type":"say","who":"杜预","text":"你好自为之吧！"},{"type":"say","who":"杜预","text":"（我又何尝不知相国也在默许这样的行为，其实最想杀邓艾的恐怕就是他吧。）永安之危永安城议事厅"},{"type":"say","who":"杨宗","text":"成都陷落的消息现在已经传得到处都是，如果我们不采取行动的话，永安可是非常危险。"},{"type":"say","who":"罗宪","text":"那么就把那个散播消息的人杀了，这样应该可以稍微撑一段时间。"},{"type":"say","who":"杨宗","text":"事情可没有这么简单吧，你我都知道成都不但沦陷，而且不久前还发生钟会叛乱，甚至连大将军都死在那场乱事。"},{"type":"say","who":"罗宪","text":"我知道…一时之间我也拿不定主意。"},{"type":"say","who":"杨宗","text":"更可恶的应该是东吴，看那步协率领的军队，名义上是要增援，实际上却是想偷袭我们。"},{"type":"say","who":"罗宪","text":"真给右大将军说对了，东吴和我们本为唇齿相依之邦，没想到不同情我们的苦难，还在这时候背弃盟誓，偷袭我们。"},{"type":"say","who":"杨宗","text":"从现实角度来看，大汉已亡，东吴大概也撑不了多久，干嘛向他们投降。"},{"type":"say","who":"罗宪","text":"好，就让我来痛击他们。"},{"type":"say","who":"罗宪","text":"命你突围北上，去找魏军支援，就说我们永安已经是他们领土，请他们增援。"},{"type":"say","who":"杨宗","text":"那可不够，还得准备文武官员的印信，还有人质才行。人质最好要美一点的…"},{"type":"say","who":"罗宪","text":"你该不会中途想做什么吧？"},{"type":"say","who":"杨宗","text":"我杨宗可以以人格保证，绝对清廉可靠。"},{"type":"say","who":"罗宪","text":"算了吧，你和关索、霍弋并称三大损友，整个大汉何人不知？罗宪率领永安区区两千人军队，先是大破步协军队，又挡住陆抗攻势超过半年。终于在半年后等到胡烈的援军，永安因而解围。司马昭嘉许罗宪的忠勇，任命他留永安原官，加号陵江将军，封万年亭侯。南中动向南中蜀汉军军营"},{"type":"say","who":"霍弋","text":"这件事情关系重大，我也不敢随便作主，所以请大家一起来商量一下。"},{"type":"say","who":"霍弋","text":"刚才接到成都那边的消息，因为钟会叛乱，整个成都成为战场，死伤无数。"},{"type":"say","who":"霍弋","text":"其中大将军和左车骑将军、蒋护军兄弟、太子等人都已经确认罹难了。"},{"type":"say","who":"赵统","text":"怎么会这样？！"},{"type":"say","who":"刘敏","text":"我认为大将军早就有预感事情会变成这样，所以才会要我们先逃到南中去。"},{"type":"say","who":"刘敏","text":"只可叹我没有保护好蒋家两兄弟，这样我怎么去面对外兄？"},{"type":"say","who":"关索","text":"伯约他还真傻，他失败后造成这样的灾难，恐怕后世的人会一直嘲笑他。"},{"type":"say","who":"霍弋","text":"还有一件对关将军来说很不幸的消息，我听说成都关家被魏将庞会趁乱灭门了。"},{"type":"say","who":"关索","text":"什么？！庞会？难道是庞德的儿子？"},{"type":"say","who":"旁白","text":"▶ 是的。"},{"type":"say","who":"关索","text":"该死…我居然没有想到这一点，庞德的儿子居然会跟著来进攻？"},{"type":"say","who":"赵统","text":"因为曹贼的侵攻，我们每个人几乎都失去了自己的亲人。不过我们没有时间悲伤下去了。"},{"type":"say","who":"关索","text":"可恶呀…二哥，我居然没办法守住您的儿子…我到底在做什么？！"},{"type":"say","who":"花鬘","text":"关索，你冷静点…现在你是关家最后的血脉，一定要保重自己的啦。"},{"type":"say","who":"关索","text":"我知道，我也知道…"},{"type":"say","who":"孟琰","text":"（看来俺真是一点机会也没有，这该死的关索真是人在福中不知福。）"},{"type":"say","who":"张嶷","text":"（如果当初我能再坚持一点，率军去阴平小道埋伏，说不定就没有今天这样的灾祸了。）"},{"type":"say","who":"霍弋","text":"我想到一个方式可以保护我们所有人的安全，只是不知道大家肯不肯接受。"},{"type":"say","who":"霍弋","text":"南中地区对于贼人来说，山多崎岖，气候炎热，完全没有进攻的欲望。"},{"type":"say","who":"霍弋","text":"如果我们能名义上投降他们，我想他们会因为考虑到治理的困难，让我们保有实质的独立性。"},{"type":"say","who":"霍弋","text":"当然这计画需要南中大族的协力，不知道孟将军愿意协助我们吗？"},{"type":"say","who":"孟琰","text":"我们孟氏一族一定会支持大汉政权的，这点请放心的啦。"},{"type":"say","who":"孟琰","text":"其他大姓像是焦、雍、娄、爨、量、毛、李等也一定会配合的啦。"},{"type":"say","who":"赵统","text":"我同意，至少我们可以维持一个实质的大汉政权，也可以收容逃难的军民。"},{"type":"say","who":"刘敏","text":"既然大将军都肯牺牲自己的名誉，我们又为什么不行。"},{"type":"say","who":"霍弋","text":"那么我就向曹贼递降书了。"},{"type":"say","who":"张嶷","text":"等一下，我听说司马家因为自诩是儒学名家，所以特别喜欢忠孝节义的故事。"},{"type":"say","who":"张嶷","text":"不如我们也来编个让司马昭爽孜孜的故事吧。"},{"type":"say","who":"霍弋","text":"（等一下，听说司马家因为自诩是儒学名家，所以特别喜欢忠孝节义的故事。）"},{"type":"say","who":"霍弋","text":"（不如我们也来编个让司马昭爽孜孜的故事吧。）霍弋递降书，上书提到：“我曾经听说，人生在世，有三位君长，父、母、君王，而事奉他们的道理，完全一样。三者有难，则为他们效死。而今，我的国家败亡，主上归附；牺牲性命已无对象。所以向陛下投靠，忠心不二。”司马昭嘉许霍弋的节操，任命他当南中都尉，对南中之事不加干涉。行馆预言成真"},{"type":"say","who":"陈寿","text":"老师，没想到您预言的那么准，当初在宫门留下的十二字真言居然成真，大汉果然在一年后灭亡了。"},{"type":"say","who":"谯周","text":"这没什么，不过是从杜琼先生的言辞去推论的，并没什么创新的地方。"},{"type":"say","who":"陈寿","text":"不，这还是很厉害呀，不畏惧像张裕那样的下场，拥有说出实话的勇气实在是非常可贵。"},{"type":"say","who":"谯周","text":"不过，后人会怎么看我呢？认为我早就已经和大魏互通声息？"},{"type":"say","who":"陈寿","text":"老师，明明就不是这样，您是热爱益州这片土地才会说出这些话，不是吗？"},{"type":"say","who":"谯周","text":"我认为天命归大魏，所以不认同姜维出兵造成我益州人伤亡，那只不过是徒劳无功的举动而已，人终究胜不了天命。"},{"type":"say","who":"陈寿","text":"老师说得是，粗有文武，志立功名，而玩众黩旅，明断不周，终致陨毙。"},{"type":"say","who":"谯周","text":"是呀，志立功名，玩众黩旅，明断不周，终致陨毙…谯周因劝后主刘禅降，遂被封为阳城亭侯，迁骑都尉，最后被封散骑常侍，于公元二七零年冬天去世。谯周精通六经与天文现象，并以反对姜维出兵的“仇国论”闻名于后世。他一连串强调曹魏消灭蜀汉的言论，究竟是真的相信这样的占卜结果，还是为别有用意则不得而知。只是他的劝降确实也象徵部分益州人对蜀汉政权的离心。他的弟子陈寿后来并没有被晋朝重用，不过他编写的《三国志》至今仍四处流传。老将之死行馆"},{"type":"say","who":"廖化","text":"德艳…"},{"type":"say","who":"宗预","text":"我活到这把岁数，就算死也算是天寿。但以这样的方式死去，还是很不甘心。"},{"type":"say","who":"廖化","text":"我的身体也一天不如一天，恐怕是撑不到洛阳了。"},{"type":"say","who":"宗预","text":"亡国之臣本来就没有这么好当，特别像我们这些经历过开国时期的人，哪受得了这样的打击。"},{"type":"say","who":"廖化","text":"真的好痛苦，早知道当时就和伯约一起战死算了。"},{"type":"say","who":"宗预","text":"唉…要是我们当初能齐心协力，又怎么会落到这样的下场？毁掉大汉的，不是邓艾，而是我们自己呀。"},{"type":"say","who":"廖化","text":"或许你说得对吧，但现在后悔也来不及。只有到那边再向伯约和关将军谢罪。"},{"type":"say","who":"宗预","text":"（伯苗，我辜负了你的期待，还眼睁睁看著大汉灭亡。有著这样罪孽的我，还有机会到和你一样的地方？）公元二六四年初，镇军大将军宗预和右车骑将军廖化在被护送前往洛阳的途中病逝。恩仇消逝雍州"},{"type":"say","who":"马岱","text":"到最后，不但伯约死了，居然连杨阜的女儿都死了。"},{"type":"say","who":"马岱","text":"当大家都在为了心中的理想而奋斗，我却还是停留在原地，只是为了仇怨而战。"},{"type":"say","who":"马岱","text":"到最后什么都没有得到，不但赔光了弟兄，还做出许多后悔至今的事。"},{"type":"say","who":"马岱","text":"伯约，接下来我那残余不多的人生将为马家的存续而活。"},{"type":"say","who":"马岱","text":"我会告诉他们这些年发生的事情，让他们知道永远不要再犯下自己曾犯的错误。降伏的勇气剑门关军营"},{"type":"say","who":"阎宇","text":"长元，你是说要我们投降？"},{"type":"say","who":"樊建","text":"成都发生的事情，或许你们或多或少都有耳闻了。大将军的复国计画失败，已经以身殉国了。"},{"type":"say","who":"柳隐","text":"不！不！为什么会这样？为什么老大苦了一辈子，最后还给他这样难堪的结局？"},{"type":"say","who":"樊建","text":"柳将军，我希望你能冷静一点，现在就算是悲伤或发怒都无济于事。"},{"type":"say","who":"樊建","text":"这里有将近四万的军队，如果不赶快表明态度，恐怕成都和长安两地的军队将发动攻击，到时就来不及了。"},{"type":"say","who":"王含","text":"所以要我们表明恭顺的态度，让那些贼军不至于把我们当敌人？真是屈辱到极点。"},{"type":"say","who":"向充","text":"我们的士兵都还有斗志，加上大将军遇害，一定能发挥更强的战斗力。"},{"type":"say","who":"来忠","text":"就算战死，也好过当投降的亡国奴！"},{"type":"say","who":"阎宇","text":"要我投降，比杀了我还痛苦，这种事情实在是做不到。"},{"type":"say","who":"王含","text":"要死就死，大汉臣子有哪个怕死的？"},{"type":"say","who":"樊建","text":"你们不要再执迷不悟了！眼下四万将士的性命操在你们手上，不要再说这些不负责任的话了。"},{"type":"say","who":"柳隐","text":"我认为你说的有道理。虽然我满腔的悲愤，但是也不能不考虑到老大要我们留在这里的用意。"},{"type":"say","who":"柳隐","text":"因为这场战争死亡的人已经够多了，难道大家还想要继续制造死伤才满意？想想这四万名弟兄都有亲人…"},{"type":"say","who":"樊建","text":"各位，投降是屈辱，需要比战死更大的勇气，拜托你们就听我这一次吧。"},{"type":"say","who":"柳隐","text":"（老大，其实我是已经对这个政权心灰意冷了，在你死以后，我没有理由再为这个政权和昏君卖命。）"},{"type":"say","who":"向充","text":"（我知道柳将军在想什么，但是他想的事情也不无道理，长久以来我们的奋斗是为了什么？得到的又是什么？）"},{"type":"say","who":"来忠","text":"（个人的荣辱和四万名弟兄的生命，轻重可是一目瞭然。我已经制造了那么多的罪孽，又岂能在现在多加一笔？）乱事终结长安城议事厅"},{"type":"say","who":"裴秀","text":"一切就如同相国所料，钟会造反失败被杀，邓艾也死在这场乱事中。"},{"type":"say","who":"裴秀","text":"（钟会果然死了…也不枉费我让邵悌等人不断散布你会造反的传言，也不枉费我推荐卫瓘来盯死你的用心。）"},{"type":"say","who":"裴秀","text":"（不过，我的计画虽然周全，但最后要成功还是得要你自己造反呀。）"},{"type":"say","who":"裴秀","text":"（聪明一世的你到最后就毁在自己的野心上，你也怪不了我。）"},{"type":"say","who":"司马昭","text":"公主这招震山敲虎果然厉害，一口气解决掉两个心腹大患。"},{"type":"say","who":"曹绫","text":"（果然失败了，本来只要钟会能够夺取手上军队的指挥权，或是直接用蜀将，在战场上交锋还有一丁点机会取胜。）"},{"type":"say","who":"曹绫","text":"（钟会想必在最后关头没有狠下心诛杀手下将领才会造成这样的结果，像他这样聪明的人会犯下这种错误，岂非天意？）"},{"type":"say","who":"曹绫","text":"（既然连这最后的计策也失败，看来司马昭要篡位的脚步已经是挡不住了。）"},{"type":"say","who":"曹绫","text":"那个…姜维他的状况如何？"},{"type":"say","who":"裴秀","text":"姜维煽动钟会谋反，跟著钟会一起被斩杀…据说我军因为愤恨姜维阴谋害他们，所以连他的妻子一起被杀。"},{"type":"say","who":"曹绫","text":"什么？！姜维他死了…妻子…又是怎么回事？"},{"type":"say","who":"司马昭","text":"公主怎么慌乱成这样？你怎么会这么重视那个人？"},{"type":"say","who":"曹绫","text":"整个蜀地最大的支柱就是他，得到他更胜过得到蜀地。"},{"type":"say","who":"司马昭","text":"说得也是，比起心怀诡诈的钟会或是难以驾驭的邓艾，这个人确实是我梦寐以求的大将。"},{"type":"say","who":"曹绫","text":"我是为了大魏痛失一个人才而悲伤。少了他，或许灭吴还得多等一段时间。"},{"type":"say","who":"司马昭","text":"公主爱才的表现还真像是武皇帝…"},{"type":"say","who":"曹绫","text":"（我为什么说得出这种话来？明明现在我心痛得要命…今天能站在这里全都是你的支持，然而你居然先走一步？）"},{"type":"say","who":"曹绫","text":"（想要不顾一切痛哭，但是在敌人眼前却不可以掉下一滴眼泪，这真的好痛苦。）"},{"type":"say","who":"文官","text":"因为这次灭蜀大功，圣上想要封您为晋王，请您即刻回洛阳接受册封。"},{"type":"say","who":"司马昭","text":"嗯…我知道了。即刻启程回到洛阳。"},{"type":"say","who":"司马昭","text":"（晋王也到手，接下来就是禅让了，一切总是进行得这么顺利。）"},{"type":"say","who":"司马昭","text":"（只是不知道为什么，我却有种空虚感，莫非是因为邓艾、姜维等英雄都已经离世的关系？还是因为曹绫已经挡不住我？）"},{"type":"say","who":"曹绫","text":"（纵然现在已经无法再有什么作为了，但我还是有可以努力的目标。至少在最后，帮曹家争取最后一点生存空间也好。）公元二六四年三月十九日，曹魏皇帝曹奂封司马昭“晋王”，增加采邑十个郡。两个月后，追封司马懿为“晋宣王”，司马师为“晋景王”。此时，距离篡位只剩下一个步骤了。乐不思蜀洛阳相国府"},{"type":"say","who":"刘禅","text":"不知道晋王您今天要招待什么，还真让人期待呢。"},{"type":"say","who":"司马昭","text":"孤似乎也邀请了安乐公你的旧属，怎么都没有跟著来？"},{"type":"say","who":"刘禅","text":"他们怕触景生情，所以并没有前来。"},{"type":"say","who":"贾充","text":"（晋王曾经对我说过，一个人没有灵性，居然能到如此地步，纵然诸葛亮也无法辅佐他长久不坠，更何况姜维。）"},{"type":"say","who":"司马昭","text":"你是不是很想念巴蜀？"},{"type":"say","who":"刘禅","text":"此间乐，不思蜀！东吴新君建业皇宫"},{"type":"say","who":"张布","text":"没想到陛下就这样走了…"},{"type":"say","who":"濮阳兴","text":"因为蜀国灭亡，之后攻略永安不顺利，加上交州吕兴反叛，现在我们大吴真的很危险。"},{"type":"say","who":"张布","text":"所以就算陛下用手指托我们拥立年幼的太子即位，我们也不可以轻易答应。这国家需要年长的君王。"},{"type":"say","who":"濮阳兴","text":"可是一时之间我们到哪里去找年长的君王？大皇帝的皇子辈除了齐王孙奋这个声名狼藉的家伙以外，全都死光了。"},{"type":"say","who":"张布","text":"皇孙的话，我一下子也想不到还有谁。"},{"type":"say","who":"万彧","text":"在下倒是有个不错的人选可以推荐。"},{"type":"say","who":"张布","text":"这不是左典军吗？"},{"type":"say","who":"濮阳兴","text":"到底是什么人可以让你如此看重？"},{"type":"say","who":"万彧","text":"乌程侯是故太子孙和之子，才能见识卓越，英明而有决断力，奉公守法，好学不倦。若说他像谁嘛…在下是想到一个人。"},{"type":"say","who":"张布","text":"像何人？"},{"type":"say","who":"万彧","text":"长沙桓王。孙策再世乌程议事厅"},{"type":"say","who":"马扁","text":"恭喜皇上，贺喜皇上！左典军的游说似乎奏效了，马上就会有人来迎接您前往建业。"},{"type":"say","who":"孙皓","text":"嗯…"},{"type":"say","who":"马扁","text":"皇上您在想什么？是不是您手头的国务机要费不够用？如果是的话，就交给阿扁来张罗。"},{"type":"say","who":"孙皓","text":"你们夷州人只会在意这点小事？"},{"type":"say","who":"马扁","text":"偶们夷州是个鬼岛嘛，每个人都穷到没裤子穿，只可惜被圣朝带过来的人只剩下偶一个而已。"},{"type":"say","who":"孙皓","text":"朕只是在想，蜀国灭亡，天下被魏国夺去三分之二会不会还让得不够多？"},{"type":"say","who":"孙皓","text":"不久以后，魏国大概也会被司马家篡夺，到时候就是我和司马家的对决。"},{"type":"say","who":"孙皓","text":"希望司马家不要轻敌，如果他们以为朕是刘禅之流，他们绝对会后悔的。"},{"type":"say","who":"宁随","text":"在下丹阳刁玄…"},{"type":"say","who":"孙皓","text":"丹阳？你的口音怎么不像是丹阳人。再说，你当朕没看过真的刁玄？他可是宣太子（孙登）的宾客。"},{"type":"say","who":"宁随","text":"果然是眼光锐利，不愧是在下看上的英主。"},{"type":"say","who":"宁随","text":"在下曾经听闻水镜先生司马徽与刘廙论运命历数，不知道陛下有没有兴趣知道？"},{"type":"say","who":"孙皓","text":"请说。"},{"type":"say","who":"宁随","text":"黄旗紫盖见于东南，终有天下者，荆、扬之君乎！"},{"type":"say","who":"孙皓","text":"哈哈哈哈哈，荆扬之君吗？你这个假刁玄还真有意思，朕还想多听听你的话。"},{"type":"say","who":"马扁","text":"（赶羚羊勒，哪冒出来一个死神棍抢了阿扁的饭碗。）"},{"type":"say","who":"宁随","text":"（事情不会这样结束的，司马家不会这么容易就夺取天下的！）"},{"type":"say","who":"宁随","text":"（丞相与伯约死后，我更要替他们发扬对抗司马家的遗志。即使让孙皓变成第二个秦皇也在所不惜！）吕布被缚匈奴之子洛阳质子府"},{"type":"say","who":"刘渊","text":"请问得到的答覆是？"},{"type":"say","who":"王浑","text":"不行呀，朝中大臣们还是认为“非我族类，其心必异”，完全不打算给你机会。"},{"type":"say","who":"刘渊","text":"这点我倒是不意外，毕竟我们匈奴人和汉人打了好几百年的仗，一时间要对我们委以重任，根本是不可能的事。"},{"type":"say","who":"王浑","text":"那些人就是死脑筋，也不想想像你这样饱读诗书的人，哪里还是危险的蛮族。"},{"type":"say","who":"王浑","text":"过去我爹一直称赞你是个人才，当面相见之后更觉得不得了。"},{"type":"say","who":"王浑","text":"以你的学问和武艺，哪怕是洛阳的朝中文臣武将也没几个人是你的对手。"},{"type":"say","who":"刘渊","text":"不用担心，日后还有得是机会。就算相国平灭巴蜀，作乱之人仍然存在呀。"},{"type":"say","who":"刘渊","text":"看看河西的秃发鲜卑和江东的吴贼，只要他们还在，我又何愁没有表现机会？"},{"type":"say","who":"王浑","text":"说得也是，到时我会向相国再次推荐你。"},{"type":"say","who":"王浑","text":"（我们父子看的绝对没错，像这样杰出的人才，绝对不能让他跑掉。在我大魏失去邓艾之后，此人正是后继之人。）"},{"type":"say","who":"刘渊","text":"（到了洛阳之后，才发现并州实在太渺小。我们匈奴人怎么可以只窝在那小小地方苟且偷生？）"},{"type":"say","who":"刘渊","text":"（我们匈奴祖先和汉朝宗室约为兄弟，流有汉朝的血，实在应该继承汉室，和司马家一较高下。）"},{"type":"say","who":"刘渊","text":"（我就在洛阳慢慢累积实力，结交名士。总有一天，我们匈奴人会再度重拾往日的光荣。）鲜卑之王河西鲜卑王营帐"},{"type":"say","who":"秃发机能","text":"听说蜀国灭亡了，想不到过去那个能以少数军队撼动整个魏国的小国，最终还是难逃灭亡的命运。"},{"type":"say","who":"若罗拔能","text":"这样看来，魏国的势力恐怕是无法憾动了。难道我们真的要像姚柯回那没出息的家伙那样，对魏国表示恭顺？"},{"type":"say","who":"秃发机能","text":"忘记汉人怎么对待外族？羌人被汉人屠杀，根本就是“绝其本根，不使能殖”，这些我们可是看得清清楚楚。"},{"type":"say","who":"若罗拔能","text":"所以说，大王应该是要反抗了？"},{"type":"say","who":"秃发机能","text":"我刚继承祖父的部族，势力还不完全稳固，一旦我稳固统治，也就是这些汉人的末日了。"},{"type":"say","who":"若罗拔能","text":"好呀！杀光汉人，还我河西！"},{"type":"say","who":"秃发机能","text":"呵呵呵…我倒要看看汉人有没有真正有骨气的将领敢和我对决。慕容鲜卑辽东"},{"type":"say","who":"慕容涉归","text":"现在大魏独强已经是确定的事，看来我当初决定要把部族迁到辽东郡是正确的决定。"},{"type":"say","who":"慕容涉归","text":"虽然比起当年轲比能威震各部和汉人对抗要逊色很多，但是想想他的悲惨下场，还是像我现在比较好。"},{"type":"say","who":"慕容涉归","text":"靠著大魏“大单于”的封号，我才能和段氏、宇文氏等部相斗。"},{"type":"say","who":"慕容涉归","text":"只是…万一哪天大魏或是取代他的中原王朝衰落，我还要继续低声下气？吕布被缚草付应王羌王营帐"},{"type":"say","who":"姚柯回","text":"蒲怀归啊，原来是你。找本王有什么事情啊？氐族兵我是代表我们蒲氏部族来向羌王您求和的。"},{"type":"say","who":"姚柯回","text":"你们氐奴哪有资格和我谈条件，要么就投降我，向我屈服。氐族兵我实在不懂羌王为什么要对我们追杀到底，帮著汉人屠杀我们氐族有什么好处？等到我们都死完了，接下来就轮到你。"},{"type":"say","who":"姚柯回","text":"光冲著西羌都督这个官位就值得了。靠著这官位，我做什么都畅行无阻。"},{"type":"say","who":"姚柯回","text":"更何况大魏对我这个叛服不定的人毫无信赖感，如果不做些表示，只怕到后来又把矛头对向我们。氐族兵那也不能就攻击我们呀，我们什么都没做，我们也是支持大魏的部族。"},{"type":"say","who":"姚柯回","text":"怪就怪自己弱吧，蠢人！氐族兵你这样逼下去，是要逼到我们氐族人内迁到中原？"},{"type":"say","who":"姚柯回","text":"那是你们的事。像你这种低下的氐奴，哪能明白我建国之志？"},{"type":"say","who":"姚柯回","text":"（现在最大的问题是，我何时能有个儿子？姚弋仲这个名字我为父早给你取好了，你快些降生吧。）氐族兵（这羌人的嘴脸真令人讨厌。我发誓，我总有一天会让我们蒲氏部族爬到你们羌人头上来。）氐族兵（你不是说我们弱小吗？那我就给我的儿子起个大气些的名字！嗯……就叫蒲洪好了。）上党羯族上党附近"},{"type":"say","who":"石周曷朱","text":"我认识的汉人中，就属你最有气魄。"},{"type":"say","who":"石周曷朱","text":"只是像你这样的人，为什么没有入朝为官，而是跑到我们这贫穷的部落？"},{"type":"say","who":"句扶","text":"事到如今我也不想隐瞒了，我是故汉将领，姓句名扶，字孝兴，而且也不是汉人。"},{"type":"say","who":"石周曷朱","text":"賨人吗？原来如此。从这么远的地方过来，你也真是辛苦了。"},{"type":"say","who":"句扶","text":"我浪迹天涯，就是为了找寻能够反抗魏国和司马家的人。"},{"type":"say","who":"石周曷朱","text":"可惜你真的找错人了，我们羯族部落贫困无比，人丁也不旺，依附汉人都来不及了，哪有能力反抗。"},{"type":"say","who":"句扶","text":"不，看到羯人在如此恶劣环境中还不屈不挠的精神，我认为我没有看错。"},{"type":"say","who":"石周曷朱","text":"说真的，我也不是安于现状的人。资源被汉人掠夺殆尽不说，还不停抓我们的人去充丁，实在让人无法忍受。"},{"type":"say","who":"句扶","text":"正是如此，如果我们不早点有所觉悟，只会永远被汉人牵著鼻子走。"},{"type":"say","who":"石周曷朱","text":"你要是不嫌弃的话，我想和你结拜兄弟。"},{"type":"say","who":"句扶","text":"结拜？"},{"type":"say","who":"石周曷朱","text":"是呀，我还希望你指导我将来要出世的孩子，让他成为远超过我这无能老爹的大将。"},{"type":"say","who":"句扶","text":"那还真是荣幸呀…如果可以的话，我可以帮忙取名吗？"},{"type":"say","who":"石周曷朱","text":"当然可以，你想给他取什么名字？"},{"type":"say","who":"句扶","text":"叫做石勒如何？既有勒马中原之意，也有将部络组织起来，勒以文明之意。"},{"type":"say","who":"石周曷朱","text":"石勒…还挺威武的嘛…想不到你会对我这未出世的儿子有如此期待。"},{"type":"say","who":"句扶","text":"（我看得没错，羯族有这个本事，虽说石周曷朱的格局不大，但如果说我好好培育下一代，说不定真的可以翻盘。）"},{"type":"say","who":"句扶","text":"（到时候一定要好好告诉石勒曹操和司马懿的事情，让他能分辨什么样的人该尊敬，什么样的人该鄙视。）"},{"type":"say","who":"句扶","text":"（抱歉了，既然大将已经不存在，我也没有必要再为汉人效力。今后的句扶将是一介賨人，永远不会回头了。）怨恨的种子东莱王家"},{"type":"say","who":"王颀","text":"真令人感叹，和我同时平定蜀地的两位太守，不久后也都当到了州刺史。"},{"type":"say","who":"王颀","text":"只有我还是停留在太守的等级，这就表示朝廷对我的态度就是这样。"},{"type":"say","who":"王颀","text":"因为我效命过毌丘俭和邓艾这两名叛将，所以这辈子都无法翻身，就算我想要为国效命都难。"},{"type":"say","who":"王颀","text":"不过我一点也不后悔。毌丘将军和邓将军是我看过最有骨气和忠诚心的大将，比起当朝许多高官要伟大得多。"},{"type":"say","who":"王颀","text":"既然朝廷还惦记著当年的事情，我也没有必要再为这种小鼻子小眼睛朝廷效力。"},{"type":"say","who":"王颀","text":"就算日后边疆再闹得沸沸腾腾，我也不想再向当年出征高句丽一样披挂上阵了。"},{"type":"say","who":"王颀","text":"我的孙儿昨天才出生，希望他绝对不要像我一样当官，到最后才发现什么都是空的。"},{"type":"say","who":"王颀","text":"只有靠著自己的本事，获得自己想要的东西，这才是真的。"},{"type":"say","who":"王颀","text":"这孩子的哭声与双眼异于常人，或许他还有能力颠覆这个政权也不一定。"},{"type":"say","who":"王颀","text":"对了，还没给他起名字呢……就叫王弥吧。希望他能像这名字一般，弥天盖地击垮司马家。良吏鲁芝青州议事厅"},{"type":"say","who":"文官","text":"之前您下官查的事情，现在已经查到了。"},{"type":"say","who":"文官","text":"当时跟著姜维被杀的妻子，据在场士兵说"},{"type":"say","who":"旁白","text":"▶ 是个羌人。"},{"type":"say","who":"鲁芝","text":"果然如此…那羌人女子就是这样，活得亮丽，死得也精彩。"},{"type":"say","who":"文官","text":"另外，您也该知道朝廷最近回复五等爵制，您的爵位也派下来了。"},{"type":"say","who":"鲁芝","text":"哦，是什么爵位？"},{"type":"say","who":"文官","text":"您被封伯爵，是为阴平伯。"},{"type":"say","who":"鲁芝","text":"阴平伯？哈哈哈哈哈…这是巧合还是故意呢？"},{"type":"say","who":"文官","text":"您为什么要笑成这样？阴平伯很奇怪吗？"},{"type":"say","who":"鲁芝","text":"你不知道阴平是什么地方吗？就是那个让一代名将姜伯约栽了的地方呀。"},{"type":"say","who":"鲁芝","text":"（我们曾经有类似的经历，却因为诸葛亮的北伐而使我们有著完全不同的发展。）"},{"type":"say","who":"鲁芝","text":"（曾经我想学你的壮烈，奋力反抗司马家，没想到最后还是卑躬屈膝去当人家部下，和努力到底的你相比，相差太远了。）"},{"type":"say","who":"鲁芝","text":"（不过，我还是会用我自己的方法努力下去的。就算是一点点也好，也想多接近你一点。）司马昭故去洛阳晋王府"},{"type":"say","who":"司马昭","text":"炎儿，我交代的事情…你都记住了…"},{"type":"say","who":"司马炎","text":"是的，我一定会照您的话去做。"},{"type":"say","who":"司马昭","text":"很好…如果你胆敢违背其中一项，我一定会回来找你的…"},{"type":"say","who":"司马炎","text":"不敢不敢，孩儿一定遵照父亲的指示。"},{"type":"say","who":"司马昭","text":"炎儿，你知道为什么…为父会选择你…当世子…而不是…桃符？"},{"type":"say","who":"司马昭","text":"我想过…桃符性情善良，和平稳健，名声也超过你。甚至因为他是大哥的儿子…所以让他当世子也…无妨…"},{"type":"say","who":"司马昭","text":"但是当裴秀、何曾、贾充甚至平日拥戴桃符的山涛都为你说话的时候…为父终于知道你…才是适合…担任世子的人…"},{"type":"say","who":"司马昭","text":"别以为为父不知道你在背后做的事情…"},{"type":"say","who":"司马炎","text":"父王，我…"},{"type":"say","who":"司马昭","text":"不，你拉拢人心的动作像极了宣王，光这点你就胜过桃符…"},{"type":"say","who":"司马昭","text":"下去吧，我大晋的开国君王…顺便帮我把那个人也请进来。"},{"type":"say","who":"旁白","text":"▶ 是，父王。"},{"type":"say","who":"曹绫","text":"没想到你会千里迢迢把我从邺城招来，不怕元姬生气？"},{"type":"say","who":"司马昭","text":"元姬…和我患难这么多年…一定会相信我的…"},{"type":"say","who":"司马昭","text":"今天我…是想和你做个交易…"},{"type":"say","who":"司马昭","text":"现今曹氏宗族中，就你最有力量…希望你能约束住…所有忠于魏室的大臣或皇族，让炎儿接受禅让没有阻碍…"},{"type":"say","who":"曹绫","text":"你准备拿什么和我交易？要我拱手让出兄长苦心经营的大魏，你也要有相当的觉悟。"},{"type":"say","who":"司马昭","text":"皇族禁锢令…我已经交代炎儿…一定要在即位后解除…如此你们曹家人都可以重获自由…"},{"type":"say","who":"司马昭","text":"不要担心炎儿会反悔…我们这些父祖辈的把肮脏事都做完了…他只会去扮演圣君…为了维护圣君形象，他不会反悔的…"},{"type":"say","who":"曹绫","text":"我答应你，我也不想看到曹氏宗族和忠魏大臣血流成河。"},{"type":"say","who":"司马昭","text":"斗了这么多年，曹家和司马家的怨恨不知道能不能化解？"},{"type":"say","who":"曹绫","text":"这种问题不应该问我，而是要看你们的作为…只是我们曹家可以做个例子，其身不正，虽令不从…"},{"type":"say","who":"司马昭","text":"说得也是…其身不正，虽令不从…"},{"type":"say","who":"司马昭","text":"（父亲、大哥，我们这样做正确吗？当我们有样学样的同时，后来是不是也会有人有样学样？）公元二六五年八月九日，晋王司马昭去世，世子司马炎继承王位。十二月十三日，曹魏皇帝曹奂将皇位禅让给晋王司马炎，曹魏宣告灭亡。自二二零年曹丕篡汉建立，二六五年被司马炎篡夺灭亡，立国共四十六年。然司马昭的担忧仍然成真，一百多年后，司马家的天下被权臣刘裕篡夺。出身寒微的刘裕为担心司马家的存在会威胁自己的皇位，屠杀了禅让的司马家。自此亡国君王家族皆遭屠杀，被刘裕开了先例。故汉之将洛阳皇宫"},{"type":"say","who":"司马炎","text":"朕对于姜维的事情真的很好奇，听说你是当年姜维帐下的一员，想听听你的说法。"},{"type":"say","who":"柳隐","text":"老大的一生，只可用“忠缪”来形容。"},{"type":"say","who":"柳隐","text":"忠于其国，缪于其身。不顾个人荣辱名声，把一切都奉献给国家，这就是老大。"},{"type":"say","who":"柳隐","text":"他是最聪明却也是最愚笨的人…抱歉，陛下…若是继续说下去，微臣恐怕很难控制自己了…"},{"type":"say","who":"司马炎","text":"朕已经大略明白姜维的为人了。虽是敌将，但是气节实在值得尊敬。"},{"type":"say","who":"柳隐","text":"陛下，日后一定会有很多贬低老大的声音出现，臣只希望陛下能够明辨是非，知道哪些事情才是真的。"},{"type":"say","who":"司马炎","text":"朕一定会牢记在心。"},{"type":"say","who":"柳隐","text":"陛下，臣即将要返回蜀地，也请陛下多保重。"},{"type":"say","who":"司马炎","text":"真可惜，朕认识你们这些蜀臣太晚了。才一见面就要分离，实在是感伤。"},{"type":"say","who":"柳隐","text":"（这样就好了，事情的真相就让我们这些幸存者继续传承下去，让世人知道老大真正的忠心表现。）愚公移山洛阳附近"},{"type":"say","who":"桓楷","text":"可恶！到最后还是没有办法阻止司马家篡位。大魏灭亡之后，更难为爹报仇了。"},{"type":"say","who":"嵇凛","text":"仔细想想自己可以做的事情吧。可别再想逞什么匹夫之勇，上次被我救到算是你运气好。"},{"type":"say","who":"桓楷","text":"我该怎么做？难道就这样眼睁睁看著司马家这样张狂下去？"},{"type":"say","who":"嵇凛","text":"这一代办不到，下一代再做到就好了，这就是繁衍的深意。"},{"type":"say","who":"桓楷","text":"下一代？"},{"type":"say","who":"嵇凛","text":"这样好了，我就帮我们子孙取名字，被取到名字的就继续桓家的使命。"},{"type":"say","who":"嵇凛","text":"儿子就取作桓颢…孙子叫桓彝…曾孙嘛…"},{"type":"say","who":"桓楷","text":"你居然想到我的曾孙去了！"},{"type":"say","who":"嵇凛","text":"复仇大业持续个十几代都有可能…就叫做桓温吧！"},{"type":"say","who":"桓楷","text":"桓温……总觉得这名字好像有什么深意似的……"},{"type":"say","who":"嵇凛","text":"没什么，只是听起来很威风而已。"},{"type":"say","who":"嵇凛","text":"（总不能告诉他是因为司马懿出身温县，我要他从司马家的根开始拔起。呵呵呵，要比狠毒，男人还不够格呢。）"},{"type":"say","who":"桓楷","text":"话说回来，这个名字怎么听都像个奸臣。"},{"type":"say","who":"嵇凛","text":"会吗？我倒认为他会成为可以和孙权并肩的大英雄。"},{"type":"say","who":"桓楷","text":"等一下，你刚才好像说了我们的子孙……"},{"type":"say","who":"嵇凛","text":"糟、糟糕，说漏嘴了！最后的相聚广元姜维墓"},{"type":"say","who":"夏侯霸","text":"我特地带了个人来祭拜伯约。"},{"type":"say","who":"赵统","text":"车骑将军，原来你平安无事？"},{"type":"say","who":"夏侯霸","text":"命硬就是我最大的本钱，一时之间还死不了的。"},{"type":"say","who":"曹绫","text":"小女子曹绫，前来拜谒故蜀大将军姜维的坟墓。"},{"type":"say","who":"马岱","text":"等一下，你不是贼营的公主？"},{"type":"say","who":"刘敏","text":"还贼营呢，现在都已经改朝换代了，这位公主和我们一样受到亡国之痛。"},{"type":"say","who":"柳隐","text":"我们常败军的成员应该大部分都到这里了，只有像是廖化或是宗预这些已经去世的无法到这里来。"},{"type":"say","who":"柳隐","text":"（小句，你现在在哪里呢？果然你还没有放弃…）"},{"type":"say","who":"来忠","text":"虽然无法公开表示对大将军的怀念，但是我们不约而同选在这里集合。"},{"type":"say","who":"向充","text":"（老师究竟到哪里去了？为什么今天这样重要的集会却看不到他的身影？）"},{"type":"say","who":"罗宪","text":"虽说我现在是大晋的官员，但是心还是属于大汉，所以就算冒著生命危险也要帮大将军修筑好坟墓。"},{"type":"say","who":"霍弋","text":"我和休然都是一样，虽然接受大晋的任命，但实际上还是以汉臣自居。"},{"type":"say","who":"柳隐","text":"可以不要把我和你相提并论吗？你摆明就领俸禄领得很开心，还狂吃空缺，浮报预算。"},{"type":"say","who":"霍弋","text":"我这是破坏大晋的经济嘛。"},{"type":"say","who":"关索","text":"只可惜我只能待在南中，不能找南中女人以外的换换口味。"},{"type":"say","who":"花鬘","text":"关索…你似乎对我很不满的啦…"},{"type":"say","who":"张嶷","text":"哈哈哈，都结了婚还想要偷腥，真不愧是关索呀。"},{"type":"say","who":"曹绫","text":"诸葛果，你还好吧…"},{"type":"say","who":"诸葛果","text":"我现在人在成都西山修行，每天都在为主公和杨姊姊祈福。"},{"type":"say","who":"诸葛果","text":"杨姊姊生前无法和主公在一起，至少这个衣冠冢是将两人合葬的。"},{"type":"say","who":"曹绫","text":"合葬的衣冠冢？那她可真是名符其实的姜夫人了。你羡慕她吗？"},{"type":"say","who":"诸葛果","text":"我们活著的人也有另外的使命，那就是把主公和大汉的精神传承下去，果是这样认为的。"},{"type":"say","who":"曹绫","text":"同感，活著的人都有活著的使命，至少也要让后来的人知道我们的奋斗才行。"},{"type":"say","who":"曹绫","text":"永别了，姜维…姜维竭尽全力的复国计画失败，蜀和魏两国相继灭亡，司马炎建立了晋政权，正式统治这两国旧有领地。司马懿父子经历十余年努力终于夺取魏蜀两国，并顺利称帝，但这并不代表第三代的司马炎无事可做。晋朝内外仍有许多反抗司马氏的力量正在酝酿，其中最强、最迅速的挑战便是晋武帝的宿敌孙皓。两人的战斗，才正要开始Ю絞真正的终局雒阳皇宫"},{"type":"say","who":"姜维","text":"搜救的情况如何？"},{"type":"say","who":"马隆","text":"我们搜索了附近，只看见一对小孩的尸体，看起来应该是司马衷夫妇。"},{"type":"say","who":"姜维","text":"可怜的一对小夫妻，本来以为司马家回归河内之后不会再产生牺牲者，结果没想到还是事与愿违。"},{"type":"say","who":"姜维","text":"即刻通知司马家的人，并且准备厚葬他们。"},{"type":"say","who":"马隆","text":"（不知道该怎么说，总觉得那对小夫妇就算长大也不会幸福。）"},{"type":"say","who":"马隆","text":"老师，钟会就在皇宫里面，我们是不是要冲进去解决他？"},{"type":"say","who":"姜维","text":"钟会确实是这次动乱的元凶，只要让他伏法，这次乱事就会结束了。"},{"type":"say","who":"姜维","text":"不过，我不打算亲自去见钟会，这件事情就交给你们了。"},{"type":"say","who":"柳隐","text":"这点我不懂了，平常老大你都会和敌人主将见面，怎么这次却不这么做？是因为钟会那家伙不值得尊敬？"},{"type":"say","who":"姜维","text":"这或许是原因，但也不是主要原因。"},{"type":"say","who":"姜维","text":"钟会虽然狡诈多智，靠著一个人就能掀起这么大规模的乱事。但他终究只是野心的集合体而已。"},{"type":"say","who":"姜维","text":"一但野心破灭，他就再也没有威胁，也就不需要我去亲自对付他。"},{"type":"say","who":"句扶","text":"大将你要去哪里？"},{"type":"say","who":"姜维","text":"去解决大汉未来真正的威胁…野心的尽头雒阳皇宫"},{"type":"say","who":"钟会","text":"我真的不懂，明明到这个龙椅不到数步的距离，却怎么样也跨不过去。"},{"type":"say","who":"钟会","text":"我更是不懂，为什么这些人会傻傻地为拯救这个腐朽的政权出兵。"},{"type":"say","who":"钟会","text":"彷彿这发生的一切都在和我作对一样。"},{"type":"say","who":"钟会","text":"你是什么人？"},{"type":"say","who":"女子","text":"奉命来送你去见一个人。"},{"type":"say","who":"钟会","text":"你是…"},{"type":"say","who":"女子","text":"马幼常虽然认为一切都在他计画内，但是你掀起的波澜实在太大了。"},{"type":"say","who":"女子","text":"他没有想到你可以煽动这么多人跟著你造反，你太过危险了。"},{"type":"say","who":"钟会","text":"那家伙，如果不让他自以为一切都在掌握之中，又怎么会上钩？"},{"type":"say","who":"女子","text":"同样地你也是。"},{"type":"say","who":"钟会","text":"到最后变成我们两个人在互婊吗？"},{"type":"say","who":"女子","text":"不，因为他相信，就算你有本事搞得天翻地覆，姜维也能够收拾。因为他是个不能用常识来解释的男人。"},{"type":"say","who":"钟会","text":"不，那是他走运，绝对不是他的本事！"},{"type":"say","who":"女子","text":"仔细想想，他当初看似莽撞的救援襄阳，结果让现在司马家愿意出兵。"},{"type":"say","who":"女子","text":"他在那拚死救援建业，结果不知不觉收拢东吴军民的心。"},{"type":"say","who":"女子","text":"这些你可以用运气好来解释？"},{"type":"say","who":"钟会","text":"姜维这个人究竟多谋还是少谋，我真的搞不懂了。"},{"type":"say","who":"女子","text":"你没有必要搞懂，因为你马上就要死了。"},{"type":"say","who":"钟会","text":"哈哈哈，我钟会背负著恶名而死，也是不错的结果。"},{"type":"say","who":"钟会","text":"纵不能流芳百世，也要遗臭万年！至少我能在历史上留名。"},{"type":"say","who":"钟会","text":"这个位子曹叡坐过、司马炎坐过，刘禅也坐过。"},{"type":"say","who":"钟会","text":"我比他们都强，当然有资格坐这个位子。"},{"type":"say","who":"钟会","text":"娘，您看清楚了吗？孩儿现在是皇帝了，没有人可以再欺负您，您要不要看现在的孩儿一眼？君臣的终点雒阳金镛城"},{"type":"say","who":"刘禅","text":"哦，朕的英雄，大汉的救世主呀！"},{"type":"say","who":"姜维","text":"陛下，姜维救驾来迟，还请恕罪。"},{"type":"say","who":"刘禅","text":"爱卿何罪之有，你扫平了叛逆，拯救了大汉，朕要重重给你封赏。"},{"type":"say","who":"刘禅","text":"说吧，你想要什么官位呢？当大司马？丞相？还是晋位公爵？"},{"type":"say","who":"姜维","text":"陛下，这些都不重要。"},{"type":"say","who":"刘禅","text":"你想要称王？还是受领九锡？这些也都可以商量。"},{"type":"say","who":"姜维","text":"臣也不想要这些。"},{"type":"say","who":"刘禅","text":"那就怪了，你真的什么都不想要？"},{"type":"say","who":"姜维","text":"如果真要说的话，臣只希望陛下同意一件事情。"},{"type":"say","who":"刘禅","text":"哈哈哈，不用说一件事了，就算是一百件事，朕都答应你。"},{"type":"say","who":"姜维","text":"那么臣就说了。"},{"type":"say","who":"姜维","text":"希望陛下即刻退位，将皇位让给皇子。"},{"type":"say","who":"刘禅","text":"什么？你说什么？"},{"type":"say","who":"姜维","text":"臣希望陛下即刻退位。"},{"type":"say","who":"刘禅","text":"你知道你在说什么吗？身为臣下可以这样逼迫主上？"},{"type":"say","who":"姜维","text":"就算是逼迫也好，臣也希望陛下能够遵守自己的诺言。"},{"type":"say","who":"刘禅","text":"你这作为和司马师、孙綝有什么两样？你根本是准备篡位吧。"},{"type":"say","who":"姜维","text":"不，臣对皇位一点兴趣都没有，只是认为这是对陛下最好的决定。"},{"type":"say","who":"刘禅","text":"叫朕退位是最好的决定？"},{"type":"say","who":"姜维","text":"陛下，这次的大祸究竟是谁导致的，您应该心知肚明。"},{"type":"say","who":"姜维","text":"钟会和马谡虽有才智，但陛下过度重用，委以军国重任，使两人自以为神机妙算，功高盖世，而策动谋反。"},{"type":"say","who":"姜维","text":"如果陛下恩威并施，以法度规范，就不致酿成叛乱之心了。"},{"type":"say","who":"姜维","text":"陛下引进外族、任用奸臣导致这样的灾祸，不管怎么看都是难辞其咎。"},{"type":"say","who":"刘禅","text":"朕是受害者，你有什么证据说这些是朕的主意？"},{"type":"say","who":"姜维","text":"臣握有许多陛下亲手署名的诏书，您该明白是谁拿给臣的。"},{"type":"say","who":"姜维","text":"现在陛下退位，还可以保有好名声，若是这些诏书流出去，陛下到时只怕连名声都保不住了。"},{"type":"say","who":"刘禅","text":"难道不能商量吗？朕让你称王，让你成为辅国大臣，一切权力和你共享…"},{"type":"say","who":"姜维","text":"您还不明白吗？这些完全不重要。臣只要您退位。"},{"type":"say","who":"姜维","text":"为了让陛下能够心服，臣也作出一个重大决定。"},{"type":"say","who":"诸葛瞻","text":"姜维，这一切到底是怎么回事？"},{"type":"say","who":"姜维","text":"思远，姜维无能，在援救陛下过程中被叛军残兵所杀。"},{"type":"say","who":"诸葛瞻","text":"咦？"},{"type":"say","who":"姜维","text":"之后的大将军和大将军府就交给你了。"},{"type":"say","who":"刘禅","text":"你到底想要做什么？"},{"type":"say","who":"姜维","text":"臣征战这么多年，也累了倦了，现在想要做自己想做的事。"},{"type":"say","who":"姜维","text":"就让臣陪陛下一起走下历史的舞台吧。败者塑造的历史雒阳"},{"type":"say","who":"刘谌","text":"卫将军，你能回答我吗？为什么人们会这么愚蠢，宁愿毁掉好不容易到手的和平也要自相残杀成这样？"},{"type":"say","who":"刘谌","text":"本来我以为灭晋平吴之后，天下就再也没有战争。没想到不但事与愿违，而且居然还多死了这么多人。"},{"type":"say","who":"诸葛瞻","text":"那是因为，人们都想成为胜利者，想要一手掌控一切，所以才会发生这种事。"},{"type":"say","who":"刘谌","text":"这场战争有胜利者？兄弟们全死了，雒阳被打成废墟，整个中原几乎是一片浩劫。"},{"type":"say","who":"诸葛瞻","text":"您说得没错，这场战争完全没有胜利者，大家全都是败者。"},{"type":"say","who":"诸葛瞻","text":"钟会和马谡全都死在这场乱事，包括文鸯在内的所有反叛军将领也都已经战死。"},{"type":"say","who":"诸葛瞻","text":"外族将领也死伤惨重，各部族元气大伤，就算能逃回去也很难再重整势力了。"},{"type":"say","who":"诸葛瞻","text":"您的父皇因为这次乱事而感到心灰意冷，已经决定把皇位传给您了。"},{"type":"say","who":"刘谌","text":"什么？！为什么会这样？难道是因为皇兄死亡的缘故？"},{"type":"say","who":"诸葛瞻","text":"事情的真相您不需要细想，只要知道陛下的退位是既成事实就好。"},{"type":"say","who":"刘谌","text":"是姜维对吧！是他逼父皇退位的吧！搞个半天，真正的胜利者是他。"},{"type":"say","who":"诸葛瞻","text":"您错了，不是说过没有胜利者了吗？姜维早在之前就被反叛军残兵所害，已经死了。"},{"type":"say","who":"刘谌","text":"什么？！怎么会这样…"},{"type":"say","who":"诸葛瞻","text":"这场战争大家都是败者，就算是活著的我们也都是败者。"},{"type":"say","who":"诸葛瞻","text":"但是这也是转机，因为回顾过去的历史，还没有像现在这样是由败者来塑造的。"},{"type":"say","who":"诸葛瞻","text":"不知道您愿意和在下一起继续塑造这个历史吗？"},{"type":"say","who":"刘谌","text":"这个担子真的好沉重…新朝人事雒阳宫殿雒阳大战后过了一个月…"},{"type":"say","who":"陈泰","text":"魏国丞相陈泰。"},{"type":"say","who":"陆凯","text":"吴国丞相陆凯，特来恭贺新帝登基。"},{"type":"say","who":"刘谌","text":"两位免礼，朕年纪还轻，须要各位的扶持，今后还请多多照顾。"},{"type":"say","who":"陈泰","text":"陛下客气了，魏国仍为大汉藩属，行臣下之礼乃是应该。"},{"type":"say","who":"刘谌","text":"不，这次若无魏、吴以及大家的帮忙，大汉恐怕无法度过这次的危机。"},{"type":"say","who":"刘谌","text":"今后朕会视你们为兄弟之邦，而非从属之国，还请你们多多支持。"},{"type":"say","who":"陆凯","text":"有陛下的这句话就够了，吴国今后一定会全力支持大汉，直到千秋万世。"},{"type":"say","who":"刘谌","text":"经过这次的动乱，全肇因于钟会和马谡这两位奸臣。"},{"type":"say","who":"刘谌","text":"然而朕必须要承认，太上皇虽然没有过错，在这过程中完全受制于人。但皇帝集中权力于中央的祸患还是不容忽视。"},{"type":"say","who":"任恺","text":"（没有过错吗？说得还真好听。）"},{"type":"say","who":"郤正","text":"（幸好陛下知道及时退位，让众人可以为他擦脂抹粉，要不然追究起来，皇室的威信可以说完全扫地。）"},{"type":"say","who":"刘谌","text":"因此，朕决定重新任命诸葛瞻为大司马，并且将所有的政务和军权都交给他。"},{"type":"say","who":"荀顗","text":"陛下，把所有的权力都交给大司马，那么您怎么办呢？"},{"type":"say","who":"刘谌","text":"谁说皇帝不能没有权力的？过去太上皇不也和丞相相安无事？"},{"type":"say","who":"刘谌","text":"至于说是不是会出现下一个司马家？朕不敢断言，但是现在地方上有许多屏障，情况应该和当时差很多。"},{"type":"say","who":"诸葛瞻","text":"臣愿接受这个任命，为了陛下和大汉，臣将鞠躬尽瘁，死而后已。"},{"type":"say","who":"刘谌","text":"大司马，这个天下并非朕或是刘家的天下，而是大家的天下。"},{"type":"say","who":"刘谌","text":"所以我们名为主从，实为同僚，这点还请你记著。"},{"type":"say","who":"诸葛瞻","text":"是的，臣一定会牢记在心。众人的智慧雒阳附近"},{"type":"say","who":"刘谌","text":"到现在我还一直在想，这样做对不对呢？"},{"type":"say","who":"诸葛瞻","text":"陛下，请您注意对自己的称呼。"},{"type":"say","who":"刘谌","text":"现在只有我们两人，实在不需要拘泥太多礼数。"},{"type":"say","who":"刘谌","text":"更何况我早就说过，现在我们是共同奋斗的伙伴，而非君臣关系。"},{"type":"say","who":"诸葛瞻","text":"其实不瞒陛下说，这一连串的动乱几乎让我不知所措。"},{"type":"say","who":"诸葛瞻","text":"在动乱前，还有伟大的英雄可以依靠，但在动乱之后，连这最后的依靠都没了。"},{"type":"say","who":"刘谌","text":"他也没有留给我们答案，只是要我们自己去摸索该怎么做。"},{"type":"say","who":"诸葛瞻","text":"或许这也表示英雄的时代已经过去，接下来是平凡人的时代吧。"},{"type":"say","who":"刘谌","text":"没错，我很平凡，所以需要大家的扶持才能撑起这个国家。"},{"type":"say","who":"诸葛瞻","text":"我更是平凡，在这之前，没有人引导根本就无法独立思考。"},{"type":"say","who":"刘谌","text":"哈哈哈，我现在终于明白大将军的意思。"},{"type":"say","who":"诸葛瞻","text":"哦，陛下请说。"},{"type":"say","who":"刘谌","text":"他想要的天下，应该就是现在这个样子。一个由平凡人互相扶持依赖才能继续走下去的天下。"},{"type":"say","who":"诸葛瞻","text":"嗯，这么说来，过去大家一直想要依赖英雄，结果众人变得懒得思考，而一股脑将权力和责任丢给他。"},{"type":"say","who":"诸葛瞻","text":"英雄尝到权力的滋味后害怕失去一切，于是开始压迫众人。众人因而怨恨，将攻击的矛头指向英雄。"},{"type":"say","who":"诸葛瞻","text":"于是，英雄胜利则继续压迫众人，众人胜利则杀害英雄，然后继续怠惰，并且等待新的英雄。"},{"type":"say","who":"诸葛瞻","text":"这样的循环从来没有停止过，而双方也就一直持续著受害。"},{"type":"say","who":"刘谌","text":"或许现在就是终结一切的时候，虽然前途茫茫，但总是个崭新的开始。"},{"type":"say","who":"旁白","text":"▶ 是呀…"},{"type":"scene","bg":"default","name":"文鸯的真意"},{"type":"scene","bg":"default","name":"文鸯之墓"},{"type":"say","who":"文虎","text":"没想到居然还有人肯来为二哥祭拜。"},{"type":"say","who":"赵统","text":"我虽然讨厌他，但认为他比起那个周旨要正常多了。"},{"type":"say","who":"赵统","text":"而且事后回想起来，如果不是因为他，恐怕我还是沉浸在安乐的环境底下。"},{"type":"say","who":"甘宁","text":"以为人来说，没有人比他更烂。但是以武艺来说，他还是天下无双。"},{"type":"say","who":"甘宁","text":"我能够打败他，只是因为他根本无心和我对决，否则胜负还在未定之天。"},{"type":"say","who":"文虎","text":"二哥很清楚，他的价值在太平之时就会完全消失，所以他打算用自己的生命来建立真正的太平之世。"},{"type":"say","who":"文虎","text":"邓艾在临死前见过二哥，跟他说出了自己的计画。"},{"type":"say","who":"文虎","text":"邓艾认为皇帝的权力过大是祸乱的根源，而姜维的做法根本无法有效削减皇帝的权力。"},{"type":"say","who":"文虎","text":"除了制衡的力量外，他认为最直接的办法，就是让储君消失，让皇统摇摇欲坠。"},{"type":"say","who":"赵统","text":"这么说来，他杀太子并不只是为了让陛下和大将军敌对，还有这个目的？"},{"type":"say","who":"文虎","text":"是的。皇权失去亲族的力量，会被迫去依赖外人，甚至到最后虚位化。"},{"type":"say","who":"文虎","text":"邓艾和姜维两人虽然在做法上不同，但是目标却是一致的。"},{"type":"say","who":"甘宁","text":"不过你遗漏了一件事。"},{"type":"say","who":"文虎","text":"什么事？"},{"type":"say","who":"甘宁","text":"你没想过文鸯为什么会这么听邓艾的话？"},{"type":"say","who":"文虎","text":"说起来，我也不是很懂。"},{"type":"say","who":"甘宁","text":"因为文鸯一直把邓艾看做是自己当年没能守护的父亲。"},{"type":"say","who":"文虎","text":"原来如此呀…"},{"type":"say","who":"赵统","text":"接下来你打算怎么办？"},{"type":"say","who":"文虎","text":"我受到二哥的托付，有延续文家香火的义务。"},{"type":"say","who":"文虎","text":"接下来大概只会找个地方隐居，好好度过剩下的人生吧。"},{"type":"say","who":"赵统","text":"说得也是呀，你现在还是被通缉的身份，恐怕要等到赦令下来才能随便走动吧。"},{"type":"say","who":"文虎","text":"那么你们呢？"},{"type":"say","who":"赵统","text":"我会继承父亲和弟弟的遗志，继续守护著大汉。"},{"type":"say","who":"甘宁","text":"我有该回去的地方…"},{"type":"say","who":"赵统","text":"（说得也是呀，那个诸葛尚似乎让这女人有了可以回去的地方。）谯郡附近"},{"type":"say","who":"糜照","text":"阿尚呀，我还真佩服你的度量。"},{"type":"say","who":"诸葛尚","text":"你在说什么？"},{"type":"say","who":"糜照","text":"自己的老婆居然跑去祭拜别的男人，要是我早就抓狂了。"},{"type":"say","who":"诸葛尚","text":"毕竟是战场上曾经以命相搏的对手，就像我之前也去祭拜过邓忠，这完全没什么呀。"},{"type":"say","who":"糜照","text":"你终究是太年轻了，不懂男女之情的精妙和危险之处。"},{"type":"say","who":"诸葛尚","text":"算了吧，“龙骑士”阿照居然还敢对我说教？"},{"type":"say","who":"糜照","text":"不过说真的，你有没有一点后悔？"},{"type":"say","who":"诸葛尚","text":"后悔什么？"},{"type":"say","who":"糜照","text":"娶妻终究是要取名门闺秀呀，像甘宁这种不是出身名门的就当个妾就好了。"},{"type":"say","who":"诸葛尚","text":"你在说什么呀！"},{"type":"say","who":"糜照","text":"不如这样好了，我带你去多认识一些真正的名门闺秀，到时把她们娶进来再扶正。"},{"type":"say","who":"诸葛尚","text":"阿照…别说了…"},{"type":"say","who":"糜照","text":"所谓老婆就是要带得出门，报上家名也不会觉得蒙羞才是好。"},{"type":"say","who":"糜照","text":"光看脸可爱有什么用，老了还不是会变丑，以后你一定会后悔的。"},{"type":"say","who":"诸葛尚","text":"阿照，我觉得你现在一定会后悔说这些话。"},{"type":"say","who":"甘宁","text":"糜照，你想要死一次试试看吗？"},{"type":"say","who":"糜照","text":"哇靠，什么时候出现在我背后的。"},{"type":"say","who":"诸葛尚","text":"听我说，我不会听阿照的话去找别的女人。"},{"type":"say","who":"甘宁","text":"其实你也不用担心，要开后宫我也没有意见。"},{"type":"say","who":"甘宁","text":"我是心胸宽大但没什么耐心的人，如果拈花惹草还可以，动真心就不行。听清楚了吗？"},{"type":"say","who":"旁白","text":"▶ 是。"},{"type":"say","who":"诸葛尚","text":"（话虽然是这么说的，但我很清楚，要是真的开后宫，一定会死无葬身之地……）"},{"type":"say","who":"甘宁","text":"很好。那么糜照呢？"},{"type":"say","who":"糜照","text":"关我什么事？"},{"type":"say","who":"甘宁","text":"有种再说一遍？"},{"type":"say","who":"糜照","text":"我知道了…各自的未来雒阳附近"},{"type":"say","who":"马隆","text":"两位将军真的不改变主意吗？"},{"type":"say","who":"柳隐","text":"我都年纪一把了，现在不退还准备惹人嫌吗？"},{"type":"say","who":"句扶","text":"我是常败军的元老，当大将他不在的时候，常败军也没有必要继续存续。"},{"type":"say","who":"柳隐","text":"今后是你们年轻人的时代，要好好干呀。"},{"type":"say","who":"马隆","text":"那是当然，这样才不至于愧对老师当日的托付。"},{"type":"say","who":"句扶","text":"虽说现在暂时将所有看得到的威胁排除，大汉应该不需要再作战。"},{"type":"say","who":"句扶","text":"但万一真的有这一天的时候，也请你一定要撑住。"},{"type":"say","who":"马隆","text":"现在吴魏已经没有威胁，外族也元气大伤。剩下要做的，大概也就是扫讨那些叛乱的残兵而已。"},{"type":"say","who":"马隆","text":"不过这些还不是当务之急，毕竟回复叛乱造成的创伤比较重要。"},{"type":"say","who":"柳隐","text":"看来你脑袋还挺清楚的，这样我们就能放心引退了。"},{"type":"say","who":"马隆","text":"两位征战多年，现在好不容易等到了这难能可贵的和平，还请两位多多保重，多享受点安稳的时光。"},{"type":"say","who":"柳隐","text":"那是当然，我的曾孙还等著我回家抱呢。"},{"type":"say","who":"句扶","text":"（大哥，再请稍等一下。我马上就来接你回去汉昌了。）雒阳大司马府"},{"type":"say","who":"向充","text":"真倒楣，大将军府的成员引退了大半，到最后我却得和你共事。"},{"type":"say","who":"来忠","text":"不爽不要做。"},{"type":"say","who":"向充","text":"你说得倒轻松，我把工作这样一丢，还对得起老师的托付？"},{"type":"say","who":"来忠","text":"既然这样就少抱怨一点。要知道，现在大司马府里面纯正出自大汉的人已经不多了。"},{"type":"say","who":"来忠","text":"特别是那三个从晋灭亡后加入的人更是优秀到让人害怕。"},{"type":"say","who":"向充","text":"喂，别动什么歪脑筋，那些人虽然可能让我们显得很无能，但对他们的存在对大汉可是好事。"},{"type":"say","who":"来忠","text":"呵呵呵，开玩笑的，我可不像爹那样老是没有安全感。"},{"type":"say","who":"向充","text":"你刚说的可一点也不像是开玩笑。"},{"type":"say","who":"杜预","text":"你们刚才说什么吗？"},{"type":"say","who":"张华","text":"好像提到我们三人的样子。"},{"type":"say","who":"魏舒","text":"说来听听吧。"},{"type":"say","who":"来忠","text":"哈哈哈，你们误会了。"},{"type":"say","who":"向充","text":"对对对，今后大家都是同僚，要好好相处呀。汝南袁家"},{"type":"say","who":"文官","text":"我父亲是袁胤，在袁公路灭亡之后短暂投奔刘勋，但不久后就被孙策俘虏。"},{"type":"say","who":"文官","text":"父亲不肯屈从孙氏，所以并没有任官，直到我这一代才隐姓埋名在吴郡当个小吏。"},{"type":"say","who":"文官","text":"这是家族族谱，请过目。"},{"type":"say","who":"女子","text":"我的父亲是袁耀，也就是袁公路的太子。"},{"type":"say","who":"女子","text":"在袁公路败亡之后投奔刘勋，后被孙策俘虏。接著就在孙氏政权任官。"},{"type":"say","who":"女子","text":"父亲只有我这个女儿，为了家族在东吴的地位，他将我嫁给孙奋成为侧室。"},{"type":"say","who":"女子","text":"十多年前，孙奋因卷进诸葛恪事件，加上滥杀手下官吏，被孙峻流放。"},{"type":"say","who":"女子","text":"之后我们一直住在离建业很远的章安，没想到却能因此逃过去年的兵灾。"},{"type":"say","who":"袁綝","text":"嗯…这段时间真是辛苦你了。"},{"type":"say","who":"男子","text":"我的父亲是袁熙，在幽州兵败之后大家就各自逃散。"},{"type":"say","who":"男子","text":"为了怕被曹家人追杀，所以我们一直隐姓埋名躲著。"},{"type":"say","who":"袁綝","text":"没想到二哥也还有后代留下来…看来袁家剩下来的后代比我想像得要多不少。"},{"type":"say","who":"袁綝","text":"在下这次到处广招袁家人，就是希望汝南袁家能够再次复兴。"},{"type":"say","who":"袁綝","text":"虽说经历过数次屠杀的灾祸，但只要有我们这些后代在，要复兴绝非梦想。"},{"type":"say","who":"男子","text":"那是当然，我们都愿意遵奉叔父您来当家，现在您可是大汉的高官之一。"},{"type":"say","who":"袁綝","text":"可惜在下不管怎么苦修，学问和涵养都还是无法配得上四氏三公的袁家。"},{"type":"say","who":"袁綝","text":"要是我们族人有人能够以学问出仕，在下是很愿意将当家之位让出。"},{"type":"say","who":"文官","text":"这点不用担心，就算我们这一代不行，过个几代应该就能恢复了。"},{"type":"say","who":"女子","text":"到时也希望世人能够重新正面评价祖父和伯祖那些人，不要再被曹家或孙家的记载诱导了。"},{"type":"say","who":"李明","text":"你还记得我吗？"},{"type":"say","who":"袁綝","text":"不会吧…到现在都还活著，你到底几岁了呀。"},{"type":"say","who":"李明","text":"曾祖母都活到九十以上，我这个年纪又有什么好意外的？"},{"type":"say","who":"袁綝","text":"你也看起来太年轻了吧…对了，现在不是管这个的时候，义父和义母他们应该…"},{"type":"say","who":"李明","text":"不在人世了。不过如果你想要听他们之后过得怎么样的话，我倒是很乐意分享。"},{"type":"say","who":"袁綝","text":"请一定要告知在下。"},{"type":"say","who":"李明","text":"呵呵呵，说话的口气和用语都变了，看来你是真心想要复兴袁家呀…成都宫殿"},{"type":"say","who":"罗宪","text":"老师，久未相见，学生特来相您请安。"},{"type":"say","who":"谯周","text":"令则呀，确实是好久不见了。"},{"type":"say","who":"罗宪","text":"您的脸色憔悴，气色看起来很不好，可以告诉学生发生了什么事？"},{"type":"say","who":"谯周","text":"唉，你也知道我毕生追求的梦想，就是一个在地人可以当家自主的益州。"},{"type":"say","who":"谯周","text":"前些日子太子在此地，我花了很大的力气让太子渐渐明白使用在地人的重要性。"},{"type":"say","who":"谯周","text":"没想到文鸯一杀害太子，全部心血都白费了。"},{"type":"say","who":"谯周","text":"听说新的总督要来益州，只怕又重演过去“荆楚人贵”的历史。"},{"type":"say","who":"罗宪","text":"老师您别担心，学生这次前来正是因为担任新任都督的副手，而那位都督您绝对认识。"},{"type":"say","who":"谯周","text":"哦？"},{"type":"say","who":"张翼","text":"允南，久违了。"},{"type":"say","who":"罗宪","text":"老师，张将军正是我们新任的益州都督。"},{"type":"say","who":"谯周","text":"这还真想不到呀…"},{"type":"say","who":"张翼","text":"别看他诸葛思远那样，经过这些年的历练之后，他也逐渐展现出大人物的风范。"},{"type":"say","who":"张翼","text":"更何况他自认才能远逊于丞相，所以相当讲究和其他人的合作。"},{"type":"say","who":"谯周","text":"这么说来，朝廷的旨意是允许我们自治？"},{"type":"say","who":"张翼","text":"这也算是答谢我们益州人这么多年来的牺牲奉献吧。"},{"type":"say","who":"谯周","text":"唉，多年来我一直认为益州人不该积极协力大汉参加战争，现在看来似乎是错了。"},{"type":"say","who":"张翼","text":"允南的见解也不是没有道理，我虽然侥幸靠著军功爬到现在的位子，但相对地也让许多益州子弟战死沙场。"},{"type":"say","who":"张翼","text":"现在的我，也是踏著他们的尸体爬上来的。正因如此，我必须要好好治理这块土地，才能对得起他们的牺牲。"},{"type":"say","who":"谯周","text":"伯恭，这次谯周一定尽全力帮你的忙。"},{"type":"say","who":"罗宪","text":"也请别忘记在下，身为谯老师的学生，一定不会让师门蒙羞的。关羽墓"},{"type":"say","who":"廖化","text":"关将军，现在江陵已经收复，大汉也已经完成了兴复大业，您可以真的安息了。"},{"type":"say","who":"廖化","text":"廖淳虽然不才，但是有幸参与到这光荣的作战过程，特来向您报告。"},{"type":"say","who":"宗预","text":"仔细想想，元俭你好像比关家的子孙都还要尊敬关将军嘛。"},{"type":"say","who":"廖化","text":"那是因为现存的关家子弟没有人亲身和关将军共事过，就算是关索，也几乎没有和关将军相处多久。"},{"type":"say","who":"廖化","text":"不过这样也好，留在过去的老人只需要我一个人就够了。"},{"type":"say","who":"宗预","text":"哈哈哈，这才是我认识的元俭。"},{"type":"say","who":"宗预","text":"过去的你被关将军牵绊得太深了，以至于为了弥补他的遗恨变得太过偏执。"},{"type":"say","who":"廖化","text":"或许吧，为了爬到和关将军相近的位子，我把所有竞争者都当作敌人，也不思考对方是不是也和我一样爱大汉。"},{"type":"say","who":"廖化","text":"现在回想起来，真的感到很羞愧呀。"},{"type":"say","who":"宗预","text":"现在再后悔也没什么用，毕竟你身为车骑将军，大汉安危是你责无旁贷的使命。"},{"type":"say","who":"廖化","text":"思远他终究还是年轻，要他这样的年轻人担负起整个国家，只怕他负荷不了。"},{"type":"say","who":"宗预","text":"所以这才是上天要留下我们这些老人的用途。"},{"type":"say","who":"宗预","text":"或许我们不见得可以活几年，但至少可以用这几年来减轻年轻人的负担。"},{"type":"say","who":"廖化","text":"你说得是。走吧，我们好久没有一起谈心了。"},{"type":"say","who":"宗预","text":"元俭，两个老男人谈心你认为很浪漫？南中"},{"type":"say","who":"关索","text":"想不到你们都和我一样，选择跑到南中来任职。"},{"type":"say","who":"霍弋","text":"我这边霍氏企业生意做这么大，哪可能丢下来呢？"},{"type":"say","who":"霍弋","text":"谅那个马隆再聪明，也没想到我虽然破产，但在交州又另外闯出一片天。"},{"type":"say","who":"关索","text":"我劝你下次别再睹这么大了。"},{"type":"say","who":"刘敏","text":"反正在雒阳的诸葛思远和蒋家两个小辈也不会喜欢听我啰嗦，就索性跑来南中这边养老了。"},{"type":"say","who":"刘敏","text":"虽说临走前，那个小小斌一直哭著不让我走，我可是非常为难，当下还在决定是要走还是不要走…"},{"type":"say","who":"关索","text":"拜托，我们也不喜欢听你啰嗦。"},{"type":"say","who":"张嶷","text":"关将军，倒是你为什么还是要回到这来？其实你在雒阳可以有更好的发展。"},{"type":"say","who":"关索","text":"这个嘛，毕竟我跟这块土地有难以分割的感情。"},{"type":"say","who":"关索","text":"再说，如果没有我，谁来和现在新任的孟家豪酋沟通？"},{"type":"say","who":"张嶷","text":"是呀，没有人会想到孟琰做出这样的决定，一直对大汉忠心耿耿的他，最后居然会选择背叛大汉。"},{"type":"say","who":"关索","text":"不，孟琰他就是忠心耿耿才会参加这场乱事。"},{"type":"say","who":"关索","text":"想想这些年来，大汉在这里的统治都是很薄弱，只是靠著南中豪酋来压制反对势力。"},{"type":"say","who":"关索","text":"前一阵子的交州作战，我们驱使了大量的南中人前往异地作战，他们会不满是可以预见的。"},{"type":"say","who":"张嶷","text":"没错，孟琰强迫压抑那些南中人，到最后不但自己会被吞灭，南中也还是会大乱。"},{"type":"say","who":"张嶷","text":"不如选择参加乱事，一口气消灭掉那些不安定的因子。"},{"type":"say","who":"关索","text":"是的，这样看来，我觉得丞相身边的亲信，不管出身哪里，到最后都变得很像呀。"},{"type":"say","who":"张嶷","text":"嗯，不管是孟琰、马谡或是姜维吗？"},{"type":"say","who":"花鬘","text":"关索，你为什么又跑了？这是你第几次逃婚的啦。"},{"type":"say","who":"关索","text":"有话慢慢说，我怎么会逃婚呢？只是和这些兄弟们问好而已。"},{"type":"say","who":"霍弋","text":"是呀，我们到时一定来喝喜酒。"},{"type":"say","who":"刘敏","text":"我保证一定会来致词。"},{"type":"say","who":"花鬘","text":"拜托，就只有这个不要的啦。"},{"type":"say","who":"张嶷","text":"请放心，这次关索不会逃跑了，因为他说他无法眼睁睁看著孟姑娘一个人处理这些南中事务。"},{"type":"say","who":"花鬘","text":"哦？"},{"type":"say","who":"关索","text":"毕竟我没有忘记孟琰的托付。"},{"type":"say","who":"花鬘","text":"从明天开始，我就是孟家的一族之长，你可不能再用这样的态度对我说话。"},{"type":"say","who":"关索","text":"那是当然的。雒阳太上皇寝宫"},{"type":"say","who":"张皇后","text":"陛下您还在不痛快吗，想想您也连续抱怨超过半年了。"},{"type":"say","who":"刘禅","text":"朕到现在都搞不懂他在想什么，把朕搞掉自己却什么都不要，对他有什么好处？"},{"type":"say","who":"张皇后","text":"想要梓童说一下自己的看法？"},{"type":"say","who":"刘禅","text":"咦？你刚才自称什么？"},{"type":"say","who":"张皇后","text":"陛下到现在才发现，似乎也有点迟钝了。"},{"type":"say","who":"张皇后","text":"姜维会这样做，除了他自己的政治意图外，对陛下也确实是好事。"},{"type":"say","who":"张皇后","text":"想想您退位之后，再也没有人质疑您过去为什么任用钟会和马谡，仍被歌颂为中兴之主，如此不好吗？"},{"type":"say","who":"刘禅","text":"但是朕还是想要…"},{"type":"say","who":"张皇后","text":"陛下想要变成真正的孤家寡人？以前您还有陈祗与黄皓帮忙，现在还有谁？"},{"type":"say","who":"张皇后","text":"更何况黄皓怎么死的，陛下应该也很清楚，您认为自己还能再相信别人？"},{"type":"say","who":"刘禅","text":"其实朕非常不喜欢你刚才说的那些话，但也不能否定这些话的正确性。"},{"type":"say","who":"刘禅","text":"你说得没错，朕或许真的已经不适任国君，若是继续霸著那个位子，可能到最后只会变成像孙权那样的昏君。"},{"type":"say","who":"张皇后","text":"陛下一直都是明白人，只是身边的人都看扁您了。"},{"type":"say","who":"刘禅","text":"这样好吗？跟朕一起待在这无聊的寝宫太浪费人生了，你真心爱的人应该是…"},{"type":"say","who":"张皇后","text":"陛下，梓童既然都如此自称了，为什么您还要拒绝？难道只有姊姊才是您的皇后？"},{"type":"say","who":"刘禅","text":"不是这样的…"},{"type":"say","who":"张皇后","text":"这样就好，梓童以前是大汉的皇后，现在是大汉的皇太后，还请陛下明白这点。"},{"type":"say","who":"张皇后","text":"（关索，我们毕竟也不是小孩了，彼此都有应尽的责任。过去事情就让它过去吧）港口"},{"type":"say","who":"张特","text":"请女王您放心，有我张特在，管他狗奴国有多少人，通通不是问题。"},{"type":"say","who":"台与","text":"还请您多多费心。"},{"type":"say","who":"张特","text":"不用担心啦，我这刘玄德第二的外号可不是叫假的。"},{"type":"say","who":"关彝","text":"（怎么办，真的觉得好丢人。）"},{"type":"say","who":"张遵","text":"（但是跟著大哥好像真的不会错，就暂且相信他吧。）"},{"type":"say","who":"关彝","text":"（谁不知道你眼睛在看哪里？你明明就迷上邪马台国的侍女团。真搞不懂，那些叫秋叶四十八的女人有这么迷人？）"},{"type":"say","who":"张遵","text":"（不懂就闭嘴，人家秋叶四十八可不是一般的团体，而是从一般人中挑选出来，让观众跟著她们一起成长…）"},{"type":"say","who":"关彝","text":"（杀了我吧…）"},{"type":"say","who":"女子","text":"女王，这些人真的可靠吗？"},{"type":"say","who":"台与","text":"张将军曾经是毌丘俭的手下，应该是没有问题。"},{"type":"say","who":"张特","text":"现在我就答谢各位，准备来高歌一曲。"},{"type":"say","who":"台与","text":"应该吧…"},{"type":"say","who":"女子","text":"要是这些人再这样胡闹下去，我可不可以把他们丢下海呢？"},{"type":"say","who":"台与","text":"由纪临，为什么你每次都可以满脸笑容说出这么可怕的话？腹黑属性？"},{"type":"say","who":"女子","text":"呵呵呵…"},{"type":"say","who":"嵇凛","text":"怎么？可爱的女王离开了，感觉很寂寞？"},{"type":"say","who":"桓楷","text":"不是这样的。只是觉得我们派出的援军真的能够达成任务？"},{"type":"say","who":"嵇凛","text":"别小看张特将军，他虽然看起来很不正经，但是指挥能力和智略都是顶级的。"},{"type":"say","who":"桓楷","text":"原来如此…接下来你有什么打算？天下回复和平，魏国的政务上了轨道，司马家现在也回归平淡，似乎已经失去目标了。"},{"type":"say","who":"嵇凛","text":"你的人生还真贫乏呀，难道除了对司马家报仇以外就什么都没有了？"},{"type":"say","who":"桓楷","text":"我真的想不到还能做什么了…"},{"type":"say","who":"嵇凛","text":"入赘当嵇家的女婿如何？"},{"type":"say","who":"桓楷","text":"咦？"},{"type":"say","who":"嵇凛","text":"还听不明白吗？"},{"type":"say","who":"桓楷","text":"这…不行…"},{"type":"say","who":"嵇凛","text":"为什么？难道你觉得我不够好？"},{"type":"say","who":"桓楷","text":"不，我们桓家五世帝师，怎么可以入赘呢？"},{"type":"say","who":"嵇凛","text":"真是小器的男人，我们嵇家也不差呀，至少也是当代名士的代表。"},{"type":"say","who":"桓楷","text":"不，名士哪比得上名门！"},{"type":"say","who":"嵇凛","text":"那好吧，这件事就这么算了……"},{"type":"say","who":"桓楷","text":"喂，不要啊……"},{"type":"say","who":"嵇凛","text":"呵呵呵……"},{"type":"say","who":"女子","text":"女王，很羡慕她们是吗？"},{"type":"say","who":"台与","text":"我是邪马台国的女王，再怎么样都得尽到自己的职责。"},{"type":"say","who":"台与","text":"只是…"},{"type":"say","who":"女子","text":"只是？"},{"type":"say","who":"台与","text":"还是有这么一点点的羡慕…龟山监狱"},{"type":"say","who":"马扁","text":"八月中秋山林凉，风吹大地草枝摆。甘宁老母赶羚羊，市场羊毛超级卖。赶羚羊呀草枝摆，草枝摆呀赶羚羊。"},{"type":"say","who":"马扁","text":"庭院织芭为君开，督兰山晓金桔摆。老迹埋呀金桔摆，金桔摆呀老迹埋。"},{"type":"say","who":"马扁","text":"呜呜呜，阿扁真够衰，跟著起兵不成，还被关进自己盖的监狱。"},{"type":"say","who":"马扁","text":"天啊，阿扁错了吗？阿扁错了吗？"},{"type":"say","who":"丘本","text":"关死你这贪赃枉法混蛋，你也该想到自己有今天了吧。"},{"type":"say","who":"马扁","text":"暗阴阳勒，你这死秃子，阿扁跟你有什么深仇大恨？"},{"type":"say","who":"丘本","text":"只要是贪官污吏，就是丘某的敌人。"},{"type":"say","who":"马扁","text":"关你屁事呀！"},{"type":"say","who":"丘本","text":"本来是不管我的事啦，不过现在你被关，就准备被我管啦。"},{"type":"say","who":"丘本","text":"我是新任廷尉。"},{"type":"say","who":"马扁","text":"该死的，要就一刀宰了阿扁，干嘛一口气判阿扁十几年，要关死阿扁喔。"},{"type":"say","who":"丘本","text":"你美呀，这只是你的“笼谈购地案”而已，你“国务机要费案”和“二次金改案”都还没宣判呢。"},{"type":"say","who":"马扁","text":"政治迫害呀，阿扁无罪呀！"},{"type":"say","who":"丘本","text":"去你的无罪，问问江东人，哪个不知道你马扁手握“海角七亿”。"},{"type":"say","who":"马扁","text":"呜呜呜，阿扁身体不舒服，想要申请戒护就医。"},{"type":"say","who":"丘本","text":"你这家伙花样怎么这么多？"},{"type":"say","who":"马扁","text":"你有点人性好不好，阿扁这几天拉肚子，万一像先帝那样挂掉怎么办？"},{"type":"say","who":"丘本","text":"………谧友堂"},{"type":"say","who":"皇甫谧","text":"嗯，恢复得不错，看来你是差不多痊愈了。"},{"type":"say","who":"旅人","text":"真是多谢神医，若没有您，恐怕我早就死掉了。"},{"type":"say","who":"皇甫谧","text":"不，最重要是你有著想要活下去的念头。只要有这念头，再麻烦的病都有治愈的可能。"},{"type":"say","who":"皇甫谧","text":"你先回去吧，接下来只要按时服这处方上的药就可以了。"},{"type":"say","who":"旅人","text":"多谢大夫。"},{"type":"say","who":"皇甫谧","text":"左大夫，准备看下一个病患吧。"},{"type":"say","who":"男子","text":"皇甫大夫，我到现在都一直在想，身为大夫的我们是不是能多做些什么？"},{"type":"say","who":"男子","text":"光事在这里开堂行医，能够救到的人终究是太有限了。"},{"type":"say","who":"皇甫谧","text":"不用著急，现在我们就这样慢慢一步步来，先求回复到过去华大夫在世时的荣景。"},{"type":"say","who":"男子","text":"您是说组成那支传说中的“医龙”团队？"},{"type":"say","who":"皇甫谧","text":"嗯，那只是第一步而已。"},{"type":"say","who":"皇甫谧","text":"目前我还在思考新药的开发，最近从发霉的桃子上发现了一种东西，给了我不少的灵感呢。"},{"type":"say","who":"男子","text":"哦？"},{"type":"say","who":"皇甫谧","text":"这要从生病的原因开始说起，或许我们一开始想的方向就错了。左大夫，你有兴趣听下去吗？"},{"type":"say","who":"男子","text":"那当然，能跟著大夫您行医，是我左分利此生最大的荣耀。著作郎府"},{"type":"say","who":"陈寿","text":"其实在下邀请各位前来也没有别的目的，只是想要和大家讨论一下。"},{"type":"say","who":"陈寿","text":"在下虽然奉命写史，但还是想要多知道一下遗漏的史料，毕竟魏吴两地的资料并不容易收集。"},{"type":"say","who":"韦昭","text":"早就知道了，你看过《吴书》有什么感想？"},{"type":"say","who":"王沈","text":"在下的《魏书》已经被看过了？可以给个机会让在下改改？"},{"type":"say","who":"陈寿","text":"说老实话，在下真的认为王处道的《魏书》有很多问题。"},{"type":"say","who":"陈寿","text":"别的不说，为什么连高贵乡公的事件都略掉不提？"},{"type":"say","who":"王沈","text":"拜托，在下当时被司马家控制住了，要在下怎么写？"},{"type":"say","who":"韦昭","text":"真丢脸，董狐之笔没听过吗？真是丢了史学者的脸。"},{"type":"say","who":"王沈","text":"既然敢这么说，在下也不客气了。"},{"type":"say","who":"王沈","text":"《吴书》还不是错漏百出？你就没有过度美化孙家父子？孙坚一个流氓被你写成英雄，残杀无辜还说成替天行道。"},{"type":"say","who":"王沈","text":"呵呵，更别说孙策当年怎么对袁术卑躬屈膝，然后主子大难临头就背弃他。"},{"type":"say","who":"韦昭","text":"你的《魏书》就没有鬼扯？曹操明明就对袁绍低声下气，还说成一直都反抗他。"},{"type":"say","who":"韦昭","text":"还有曹操跟袁绍借兵五千的事情到哪去了？"},{"type":"say","who":"陈寿","text":"咳，两位可否停止互相攻讦？"},{"type":"say","who":"王沈","text":"这么说来，《季汉书》其实也有不少问题。"},{"type":"say","who":"韦昭","text":"同意，对关羽的描述太过正面了，他对我们来说只是个粗暴的武人。"},{"type":"say","who":"陈寿","text":"等一下，这点请恕在下不能认同，荆州的事情难道孙权和吕蒙就没有责任？"},{"type":"say","who":"王沈","text":"这点在下倒是同意，孙权野心之大，就算不是关羽守荆州也迟早会被他偷袭。"},{"type":"say","who":"陈寿","text":"看来还有得战了，在下就去叫人买鸡排。"},{"type":"say","who":"韦昭","text":"我的那份不要切。傅佥墓"},{"type":"say","who":"蒋舒","text":"傅佥，我来看你了。"},{"type":"say","who":"男童","text":"叔叔是谁呀？"},{"type":"say","who":"蒋舒","text":"叔叔才想问小朋友是傅佥的什么人。"},{"type":"say","who":"男童","text":"我叫做傅著，他是我爹，当年镇守阳安关虽然壮烈牺牲，但却保全了大汉。"},{"type":"say","who":"男童","text":"娘跟我说，他是个了不起的大英雄。"},{"type":"say","who":"蒋舒","text":"没错，他真的是个大英雄。"},{"type":"say","who":"蒋舒","text":"不过你知道你爹是怎么死的？"},{"type":"say","who":"男童","text":"嗯…好像是一个叫做蒋舒的人害死的。"},{"type":"say","who":"蒋舒","text":"很好。那么如果蒋舒出现在你面前，你会怎么做呢？"},{"type":"say","who":"女子","text":"够了。"},{"type":"say","who":"男童","text":"娘！"},{"type":"say","who":"蒋舒","text":"原来是嫂子，这样或许更好…"},{"type":"say","who":"蒋舒","text":"我苟活在这世上其实一点意义也没有，倒不如让傅佥的家属来报仇。"},{"type":"say","who":"蒋舒","text":"是我害死傅佥的，我羡慕他的成就，嫉妒他的勇敢，所以在魏军来到时，我选择杀害这位曾经帮过我无数次的好兄弟。"},{"type":"say","who":"女子","text":"听好，我确实恨你恨到巴不得杀你。"},{"type":"say","who":"女子","text":"但是，如果真的杀了你，就只会让这仇恨的种子继续发展下去。"},{"type":"say","who":"蒋舒","text":"你不用担心，我的家人早就认为我死了，没有人会找你们报仇的。"},{"type":"say","who":"蒋舒","text":"快点吧，你们应该是对我怀抱著满腔的愤怒，如果现在不报复，还等待何时？"},{"type":"say","who":"男童","text":"娘曾经听爹说过，愤怒产生仇恨，仇恨带来苦难。"},{"type":"say","who":"男童","text":"所以我们不应该放任自己的愤怒宣泄，是不是这样呢？"},{"type":"say","who":"女子","text":"听到了吗？我们虽然恨你，但是不希望这个仇恨将我们引入黑暗面。"},{"type":"say","who":"女子","text":"既然上次的动乱你没有死，或许上天是有旨意要你活著做些有意义的事。"},{"type":"say","who":"女子","text":"回想起傅佥临死前对你说的话吧，我不认为他是对你怀抱著怨恨而死。"},{"type":"say","who":"蒋舒","text":"（你是我的兄弟呀…傅佥，我现在终于明白，你的那句话并不是矫情呀。）"},{"type":"say","who":"蒋舒","text":"呜呜呜…啊啊啊…河内司马家"},{"type":"say","who":"羊祜","text":"我们是来向司马家的各位辞行的。"},{"type":"say","who":"王浑","text":"接下来我们要去荆州上任，未来恐怕很难再来见各位。"},{"type":"say","who":"王元姬","text":"这样也好，总不能故晋旧臣都一直往河内跑，现在已经不是司马家的天下了。"},{"type":"say","who":"王元姬","text":"更何况之前参加叛乱的几乎都是故晋旧臣，我们可不希望大家再卷进麻烦了。"},{"type":"say","who":"司马孚","text":"看看我们司马家夺权的代价，从二哥这代一直到他的曾孙，几乎每代都有人横死。"},{"type":"say","who":"司马孚","text":"最可怜就是那个司马衷，他才不过七岁左右，就被钟会玩弄后杀害，实在是太不幸了。"},{"type":"say","who":"司马攸","text":"所以我才决定要参加这次平乱，让司马家摆脱混乱制造者的印象，日后才有机会过平淡的日子。"},{"type":"say","who":"羊祜","text":"您说得虽是，但日后司马家真的能够完全摆脱政治吗？"},{"type":"say","who":"王元姬","text":"不知道，但是大家会尽力去做，否则悲剧只会再次发生而已。"},{"type":"say","who":"司马攸","text":"今后大家将各奔东西，请勿再以司马家为念。"},{"type":"say","who":"司马攸","text":"你们要效忠的对象应该是大汉，司马家往后将只是一个普通的河内名门而已。"},{"type":"say","who":"旁白","text":"▶ 是，我们明白。"},{"type":"say","who":"羊祜","text":"但也请您记得，还是有人以曾经身为大晋的臣子感到骄傲的。吴军营帐"},{"type":"say","who":"施绩","text":"建业皇宫的修建情况如何？"},{"type":"say","who":"吾彦","text":"目前进度超前了两成，或许两个月后就能回去建业。"},{"type":"say","who":"施绩","text":"很好，这段日子真是辛苦大家了，不但让各位负担这么沉重的重建工作，还要出兵支援雒阳。"},{"type":"say","who":"陶璜","text":"这样好吗？现在北朝力量明显衰弱，若是我们趁机复国，他们应该没有办法出兵南下。"},{"type":"say","who":"施绩","text":"世英，你也看见这次战争的浩劫，从北到南，几乎无处不受害，难道你也像钟会或文鸯那样，是期盼战争的疯子？"},{"type":"say","who":"陶璜","text":"哈哈哈，别扣我这么大的帽子，只是开玩笑而已，能在上次战役中捡到一条小命，偷笑都来不及了。"},{"type":"say","who":"施绩","text":"（这家伙说话根本就不像在开玩笑。）"},{"type":"say","who":"周处","text":"………"},{"type":"say","who":"薛莹","text":"子隐，你在想什么？从刚才就一直在发呆。"},{"type":"say","who":"周处","text":"我只是在想齐万年那家伙死前说的话。"},{"type":"say","who":"周处","text":"过去我们虽然一直说打山越是为了大吴的长治久安，，但心底其实是不是在享受残杀山越的乐趣？"},{"type":"say","who":"薛莹","text":"那家伙的话别就太认真看待，谁都知道齐万年是个可恨的蛮族。"},{"type":"say","who":"周处","text":"真的只是这样吗？"},{"type":"say","who":"施绩","text":"族群的问题可没有这么容易解决，我也同意子隐的看法，或许我们只是在压抑自己的兽性而已。"},{"type":"say","who":"施绩","text":"不过至少现在我们已经开始反思自己的行为，比起过去应该是有很大的进步。"},{"type":"say","who":"鲁淑","text":"正是如此，现在衰弱的大吴，光是江东人和江北人合作还不足以支撑。"},{"type":"say","who":"鲁淑","text":"若是能够和山越和解，对我大吴的复兴应该会有很大的帮助。"},{"type":"say","who":"施绩","text":"嗯，目前吴王还年轻，日后许多事情都要大家的扶助，吴国的将来就拜托各位了。"},{"type":"say","who":"陶璜","text":"（真是悲惨呀，我们的戏分到这里就完了，不知道以后会不会有人做我们的故事？）"},{"type":"say","who":"陶璜","text":"（开玩笑的。一个暴君和色鬼对峙十六年的无聊故事有谁会想看？）邺城宫殿"},{"type":"say","who":"夏侯霸","text":"雒阳那边的事情都已经处理完了，现在夏侯霸正式回归魏国。"},{"type":"say","who":"曹芳","text":"嗯，我等夏侯将军已经很久了，只要你回归，魏国的人事就差不多可以底定了。"},{"type":"say","who":"夏侯霸","text":"陛下，夏侯霸岂是如此重要之人？"},{"type":"say","who":"夏侯和","text":"二哥，我们夏侯家一直是大魏的中流砥柱，更何况魏国的复兴您也出力甚多，就抬头挺胸接受魏王的赞赏吧。"},{"type":"say","who":"夏侯霸","text":"多谢魏王的抬爱，今后夏侯霸将会为您效力，粉身碎骨，在所不辞。"},{"type":"say","who":"曹芳","text":"在座的各位几乎都经历过大魏的昌盛期，大家至少都从明皇帝时期就仕官，甚至还有见过武皇帝的。"},{"type":"say","who":"何曾","text":"（那不就是老夫吗？哈哈，国有一老，如有一宝嘛。）"},{"type":"say","who":"曹芳","text":"只是希望大家明白一点，现在的魏国和大魏还是有差。虽然声威大不如前，但却是最适合存续的型态。"},{"type":"say","who":"曹芳","text":"相对于以前的大起大落，还是保持低调存续比较重要。"},{"type":"say","who":"曹芳","text":"因此，我们只需要保国安民，切勿再思考恢复大魏荣光，否则只会像这次叛乱那样，除了制造伤亡外一无所得。"},{"type":"say","who":"费曜","text":"但是防人之心不可无呀，之前雒阳那边不就恐吓过我们？日后直接派兵来袭也不是不会发生。"},{"type":"say","who":"鲁芝","text":"这点请魏王不用担心，首先是朝廷方面已经改朝换代，现任皇帝威信不足，需要我们的支持。"},{"type":"say","who":"鲁芝","text":"此外主政的诸葛瞻也是可以信赖的人物，只要他主政，我们魏国不会有问题。"},{"type":"say","who":"张虎","text":"魏王也请别忘了我，光靠著之前在河内和寿春建立的功绩，就足以让野心家忌惮三分。"},{"type":"say","who":"张虎","text":"我们不要主动攻打别人，但也要让别人知道攻打我们所需要付出的代价。"},{"type":"say","who":"曹芳","text":"确实呀，有这位张辽之后在，魏国也有著足以吓阻别人的武力。"},{"type":"say","who":"曹芳","text":"只是可以的话，我还是希望这样的小康局面能够永远维持下去。渭水"},{"type":"say","who":"马岱","text":"庞会，请原谅我必须用这种方法来阻止你。"},{"type":"say","who":"马岱","text":"你的执念太强了，强到已经让我没办法有其他的选择。"},{"type":"say","who":"杨兰","text":"我可记得，当年有个人的执念一点也不输庞会。"},{"type":"say","who":"马岱","text":"果然是你呀…"},{"type":"say","who":"杨兰","text":"我不认为庞会那家伙会责怪你，相对地，他心中似乎还期盼你去阻止他。"},{"type":"say","who":"杨兰","text":"他也知道自己的执念是罪恶，但那却是他生存的根本。"},{"type":"say","who":"杨兰","text":"如果自杀，他没办法向他老爹交代，所以他期望你杀了他，这样他才好放下这一切。"},{"type":"say","who":"马岱","text":"他真的是太可悲了…"},{"type":"say","who":"杨兰","text":"先别说庞会了，你对于自己的未来有什么打算？"},{"type":"say","who":"马岱","text":"大概找个地方隐居吧，毕竟就如同之前说过的，我也负有传承马家的责任。"},{"type":"say","who":"杨兰","text":"既然如此，你有没有兴趣陪我做一件事？"},{"type":"say","who":"马岱","text":"什么事？"},{"type":"say","who":"杨兰","text":"造反。"},{"type":"say","who":"马岱","text":"咦？五部匈奴营帐"},{"type":"say","who":"刘渊","text":"父王，这次没有达成使命，孩儿真的很惭愧。"},{"type":"say","who":"刘豹","text":"看来你还真是染上了汉人的习惯，我们匈奴人可没有这么重视荣誉，只要人活著就好。"},{"type":"say","who":"刘豹","text":"看看这次参加起事的领袖，能够活著回来的只有你一个，还不感到幸运？"},{"type":"say","who":"刘渊","text":"这点孩儿完全不懂，明明汉军当时强势无比，绝对足够将孩儿赶尽杀绝，为何他们没有那样做？"},{"type":"say","who":"刘豹","text":"你终究是年纪太小了，就算智慧过人，很多大人的事情你还是看不透。"},{"type":"say","who":"刘豹","text":"看看你的行为举止和生活习惯，和在雒阳的汉人有什么两样？"},{"type":"say","who":"刘豹","text":"要是杀了你，日后那些汉人岂不错失利用你来控制匈奴的机会？"},{"type":"say","who":"刘渊","text":"他们是希望孩儿成为下一个金日磾？"},{"type":"say","who":"刘豹","text":"没错，反正这样对我们大匈奴现在也没有坏处。"},{"type":"say","who":"刘豹","text":"主力部队都在雒阳一战失去，现在的我们哪有和汉人一战的能力？不如暂且归附，换得生存空间。"},{"type":"say","who":"刘渊","text":"原来如此，那么孩儿愿意充当和雒阳往来的使者。"},{"type":"say","who":"刘豹","text":"为了大匈奴的存续，日后你可辛苦了。"},{"type":"say","who":"刘豹","text":"想想我们能有机会和汉人谈和，也算是幸运了。"},{"type":"say","who":"刘豹","text":"那些失去领袖的羌人、鲜卑人只会被汉人像杀狗一样屠戮殆尽…"},{"type":"say","who":"刘渊","text":"他们也太可怜了，其实那些人不过是信了钟会的花言巧语，为自己族群争取权益而已…难道真的没办法拯救他们？"},{"type":"say","who":"刘豹","text":"方法还是有，除非有个人能够统整他们的力量，结成同盟来抵抗汉人…形象形象形象新盟主仇池外族营帐羯族兵盟主为什么还是没来？汉人的讨伐军都已经到阵前了。西羌兵这次讨伐军统帅是马隆，据说是个厉害角色，该怎么办？"},{"type":"say","who":"马岱","text":"怕什么？难道过去盟主拯救你们的事情"},{"type":"say","who":"旁白","text":"▶ 是假的？"},{"type":"say","who":"马岱","text":"鲜卑兵但这次汉军来势汹汹，我们真的敌得过吗？"},{"type":"say","who":"马岱","text":"真可悲呀，要是姚柯回或是秃发树机能还在，你们还会说这样的话？"},{"type":"say","who":"杨兰","text":"真是丢人呀，才不过来个马隆就让你们吓成这样，我过去可是打过诸葛亮的。"},{"type":"say","who":"马岱","text":"（虽然打输…）"},{"type":"say","who":"杨兰","text":"敌人兵力虽然多，但是经过长途跋涉，在体力和士气上都不如我们。"},{"type":"say","who":"杨兰","text":"而那个马隆也不过就我在姜维阵营时的小弟，还帮我提过枪，有什么好怕？"},{"type":"say","who":"杨兰","text":"现在大家只有通力合作，才有一线生机。否则到时候被打败，汉人绝对不留活口。氐族兵没错，我绝对支持盟主！"},{"type":"say","who":"杨兰","text":"不错，你这氐族小子有骨气，叫什么名字？氐族兵我叫飞龙！"},{"type":"say","who":"杨兰","text":"好，我收你当义子，你就改姓杨。氐族兵多谢盟主，杨飞龙这名字还真是响亮。"},{"type":"say","who":"杨兰","text":"（呼，这些人虽然骁勇，但是脑袋还是挺单纯的。）"},{"type":"say","who":"杨兰","text":"（我只是假装和汉人打仗，其实早就和马隆说好，让他们看到我们就退。）"},{"type":"say","who":"杨兰","text":"（只有这样才能避免这些人被屠杀，而我也可以藉著当盟主来抑止这些人再度起兵的念头。）"},{"type":"say","who":"杨兰","text":"（姜维呀，我为了你可是尽心尽力，你没有选我，其实我到现在还是有点生气。）影子参谋雒阳大司马府"},{"type":"say","who":"诸葛果","text":"小瞻，这件事情就如此处理就好。不用担心，你的结论是正确的。"},{"type":"say","who":"诸葛瞻","text":"多谢姊姊。虽说我贵为大司马，但还是感觉很多事情无法掌握好。"},{"type":"say","who":"诸葛果","text":"不用担心，如果有什么没办法解决的，尽管来找姊姊。"},{"type":"say","who":"诸葛瞻","text":"姊姊，其实我还是替您感到不值。"},{"type":"say","who":"诸葛瞻","text":"明明一直跟在姜维身边，没想到最后他居然丢下您而去。"},{"type":"say","who":"诸葛果","text":"那是因为我们主仆缘分已尽，请不要责怪主公。"},{"type":"say","who":"诸葛瞻","text":"还是越想越生气，耽误了您的人生，到最后却溜得不见踪影。"},{"type":"say","who":"诸葛瞻","text":"您不用担心，虽说现在要找可以匹配的对象有点难，但我一定会想办法的。"},{"type":"say","who":"诸葛果","text":"不需要了，我想一直待在这里就好。"},{"type":"say","who":"诸葛果","text":"等到事情告一段落，或许可以去成都附近学习道法。"},{"type":"say","who":"诸葛瞻","text":"难道袁将军不行吗？他对姊姊您也是一往情深，家世好，到现在也未娶…"},{"type":"say","who":"诸葛果","text":"袁将军应该有更合适的对象，例如说弘农杨家。"},{"type":"say","who":"诸葛瞻","text":"真是的，为什么您总是这么固执呢？"},{"type":"say","who":"黄崇","text":"大司马，打扰您姊弟相处时间真不好意思，但前线有要事相告。"},{"type":"say","who":"黄崇","text":"马隆将军的讨伐军日前在仇池战败…而击败他的人是…"},{"type":"say","who":"诸葛瞻","text":"杨兰。"},{"type":"say","who":"黄崇","text":"咦？您怎么知道？"},{"type":"say","who":"诸葛果","text":"那是我的主意，想要听听吗？曹家的柱石邺城郭太后墓"},{"type":"say","who":"曹绫","text":"嫂子她一辈子都是这么辛苦。"},{"type":"say","who":"曹绫","text":"早年因为本郡叛乱而被迫收尽后宫，经历许多磨难后获得皇兄的宠幸，成为皇后。"},{"type":"say","who":"曹绫","text":"但是没过多久皇兄就过世，嫂子变成太后却没有过一天好日子。"},{"type":"say","who":"曹绫","text":"被司马家掌控不说，还得面对一次又一次曹家人死去的悲伤。"},{"type":"say","who":"辛宪英","text":"至少在临终前还亲眼见到魏国复兴，曹家人能再度摆脱司马家的控制，她也算是苦尽甘来了。"},{"type":"say","who":"曹绫","text":"真是抱歉，要拉著你这个外人来探望嫂子。"},{"type":"say","who":"辛宪英","text":"别这么说，自从搬来邺城之后，公主可是一直照顾著我，而且还帮忙琇儿在魏国找到新工作。"},{"type":"say","who":"辛宪英","text":"回想起过去面对司马懿夺权却没有采取任何行动，真的感觉很惭愧。"},{"type":"say","who":"曹绫","text":"你一个人背负著辛家和羊家的前途，自然要做最安全的决定，没什么好抱歉的。"},{"type":"say","who":"曹绫","text":"更何况上次姜维得救还是依靠你，这个人情我也得还一下。"},{"type":"say","who":"辛宪英","text":"嗯…还在惦记著姜维？"},{"type":"say","who":"曹绫","text":"这段时间我真的思考了很久，或许自己是真的对他有好感吧…"},{"type":"say","who":"辛宪英","text":"这个样子还真像甄宓…"},{"type":"say","who":"曹绫","text":"说得也是，你过去也曾经和娘一起在邺城生活过。"},{"type":"say","who":"辛宪英","text":"不只这样，她那迷糊天然的样子，让我还不自觉想要多照顾她呢。"},{"type":"say","who":"辛宪英","text":"甄宓她虽然一直那样迷迷糊糊，但对自己感情却很认真，在没有得到结论以前会一直去钻牛角尖，就像您一样。"},{"type":"say","who":"曹绫","text":"只可惜我就是一直这样思考而不行动，等到最后搞清楚时已经太迟了。"},{"type":"say","who":"辛宪英","text":"没关系，缘分这种事情本来就不能太强求。"},{"type":"say","who":"曹绫","text":"也对，我就把剩下的生命用在守护魏国上面好了。"},{"type":"say","who":"辛宪英","text":"真不愧是公主，就算是失意也只难过一下，难怪当时就算是司马昭也打不倒您的意志。"},{"type":"say","who":"曹绫","text":"不，当时我真的输到山穷水尽，连求生的意志都输掉了，若不是他…"},{"type":"say","who":"辛宪英","text":"还是别勉强自己，我们回去一起来骂那些薄情的男人好了。"},{"type":"say","who":"辛宪英","text":"您知道吗？当初羊耽那个笨蛋有多不浪漫…回归平淡冀城姜家"},{"type":"say","who":"姜母","text":"维儿，这样子真的好吗？丢下这一切躲到这地方来…"},{"type":"say","who":"姜维","text":"娘，真的很抱歉。本来孩儿是想要功成名就来孝敬您，没想到最后还是让您过苦日子。"},{"type":"say","who":"姜母","text":"娘一点也不在乎这样的生活，而是维儿你的名声呀。"},{"type":"say","who":"姜母","text":"明名平定这次动乱的是你，到最后居然变成是诸葛瞻，而你却被说成是无能的统帅。"},{"type":"say","who":"姜维","text":"真的没有关系，是我要思远这样对外宣布的。"},{"type":"say","who":"姜维","text":"要是孩儿被描述成平乱英雄，那么思远他的威信就会减损，对于未来国家治理也不是什么好事。"},{"type":"say","who":"姜母","text":"这样也好，如果维儿你看得开，其实做母亲的也没什么好说。"},{"type":"say","who":"姜母","text":"对娘来说，只要在自己有生之年还看著孩子平安地活著就好。"},{"type":"say","who":"姜母","text":"只是…你真的不考虑续弦？"},{"type":"say","who":"姜维","text":"孩儿都已经这年纪了，续弦只会破坏其他女子的幸福。"},{"type":"say","who":"姜母","text":"嗯…只是做娘的都比较自私，还是希望这时候有人能照顾你呀。"},{"type":"say","who":"姜维","text":"没关系，孩儿会自己照顾自己。"},{"type":"say","who":"姜维","text":"咦？！你们怎么会…传说的英雄天水冀城"},{"type":"say","who":"旅人","text":"大家都知道，咱们冀城出了个了不起的英雄，那个人就是姜维大将军。"},{"type":"say","who":"学者","text":"嗯…他真的是英雄吗？如果真要是的话，怎么会在最后平乱时死得那么突兀？"},{"type":"say","who":"旅人","text":"这可是有重重内幕，知道这件事的，只有三个人，一个是现任大司马，一个是我，另一个不能说。"},{"type":"say","who":"学者","text":"友滑兄，鬼扯也有个限度好吗？"},{"type":"say","who":"旅人","text":"外地人愚蠢，难道我们这些家乡父老也要跟著蠢吗？"},{"type":"say","who":"旅人","text":"我可以很大胆跟各位表示，姜维大将军是为了避免底下人拥护他当皇帝才诈死。"},{"type":"say","who":"女子","text":"哦？诈死？"},{"type":"say","who":"男子","text":"这个看法有点创意。"},{"type":"say","who":"旅人","text":"别看我这样，当年我可跟过大将军南征北讨，他的英雄风范可是一直看在眼里。"},{"type":"say","who":"旅人","text":"当时我是常败军的一员，曾经有一次和邓艾打仗的时候，被邓艾带兵追杀。"},{"type":"say","who":"文官","text":"你太扯淡了吧，邓艾追杀你这小兵？"},{"type":"say","who":"旅人","text":"话可不是这样说，邓艾这老贼残忍狡猾，连个小兵都不肯放过。"},{"type":"say","who":"旅人","text":"言归正传，正当危急之时，大将军忽然从旁杀出，挥动手中长枪，一枪就撂倒一个人，最后和邓艾打起来。"},{"type":"say","who":"旅人","text":"哪知邓艾那小人，居然叫弓弩手对大将军射击，结果你们知道怎么样吗？"},{"type":"say","who":"武官","text":"大将军逃跑？"},{"type":"say","who":"旅人","text":"错，大将军不慌不忙，勇敢地挥动手中长枪挡住那漫天飞箭，数万支箭居然都无法伤他分毫。"},{"type":"say","who":"旅人","text":"而更感人的是，他居然为了保护那时候受伤的我而寸步不移。"},{"type":"say","who":"姜维","text":"太夸张了，邓艾从来没带过那么多弓弩手吧。"},{"type":"say","who":"旅人","text":"老伯安静点，人家贼人随时都能聚兵百万，几万弓弩手不过是小意思。"},{"type":"say","who":"姜维","text":"抱歉，那最后大将军怎么样了？"},{"type":"say","who":"旅人","text":"都是你在那边乱说话，让精彩的故事被打断了。"},{"type":"say","who":"旅人","text":"正当危急之时，大将军终于使出绝招，忽然间他全身散发金色闪光，你们知道那是什么？那可是传说中的“圣光气”。"},{"type":"say","who":"旅人","text":"邓艾见到大将军的实力，知道再有保留就老猫烧须了，当场运起“浑天宝鉴”心法。"},{"type":"say","who":"姜维","text":"他到底在说什么呀…"},{"type":"say","who":"姜维","text":"你来了呀？"},{"type":"say","who":"杨兰","text":"真不敢相信，明明说约好在冀城碰面，你居然跑来这里听无聊的说书。"},{"type":"say","who":"姜维","text":"抱歉，实在是有点好奇那个人会怎么说，哪知道变成神怪大战。"},{"type":"say","who":"杨兰","text":"算了，毕竟你也算是守信，再埋怨你就显得太不近人情了。"},{"type":"say","who":"杨兰","text":"走吧，在路上可要交代一下这段时间你在做什么。"},{"type":"say","who":"姜维","text":"那相对地，你也说一下这段时间在做什么吧。"},{"type":"say","who":"杨兰","text":"哦？一段时间不见，侵略性变强了？传说的英雄天水冀城"},{"type":"say","who":"旅人","text":"大家都知道，咱们冀城出了个了不起的英雄，那个人就是姜维大将军。"},{"type":"say","who":"学者","text":"嗯…他真的是英雄吗？如果真要是的话，怎么会在最后平乱时死得那么突兀？"},{"type":"say","who":"旅人","text":"这可是有重重内幕，知道这件事的，只有三个人，一个是现任大司马，一个是我，另一个不能说。"},{"type":"say","who":"学者","text":"友滑兄，鬼扯也有个限度好吗？"},{"type":"say","who":"旅人","text":"外地人愚蠢，难道我们这些家乡父老也要跟著蠢吗？"},{"type":"say","who":"旅人","text":"我可以很大胆跟各位表示，姜维大将军是为了避免底下人拥护他当皇帝才诈死。"},{"type":"say","who":"女子","text":"哦？诈死？"},{"type":"say","who":"男子","text":"这个看法有点创意。"},{"type":"say","who":"旅人","text":"别看我这样，当年我可跟过大将军南征北讨，他的英雄风范可是一直看在眼里。"},{"type":"say","who":"旅人","text":"当时我是常败军的一员，曾经有一次和邓艾打仗的时候，被邓艾带兵追杀。"},{"type":"say","who":"文官","text":"你太扯淡了吧，邓艾追杀你这小兵？"},{"type":"say","who":"旅人","text":"话可不是这样说，邓艾这老贼残忍狡猾，连个小兵都不肯放过。"},{"type":"say","who":"旅人","text":"言归正传，正当危急之时，大将军忽然从旁杀出，挥动手中长枪，一枪就撂倒一个人，最后和邓艾打起来。"},{"type":"say","who":"旅人","text":"哪知邓艾那小人，居然叫弓弩手对大将军射击，结果你们知道怎么样吗？"},{"type":"say","who":"武官","text":"大将军逃跑？"},{"type":"say","who":"旅人","text":"错，大将军不慌不忙，勇敢地挥动手中长枪挡住那漫天飞箭，数万支箭居然都无法伤他分毫。"},{"type":"say","who":"旅人","text":"而更感人的是，他居然为了保护那时候受伤的我而寸步不移。"},{"type":"say","who":"姜维","text":"太夸张了，邓艾从来没带过那么多弓弩手吧。"},{"type":"say","who":"旅人","text":"老伯安静点，人家贼人随时都能聚兵百万，几万弓弩手不过是小意思。"},{"type":"say","who":"姜维","text":"抱歉，那最后大将军怎么样了？"},{"type":"say","who":"旅人","text":"都是你在那边乱说话，让精彩的故事被打断了。"},{"type":"say","who":"旅人","text":"正当危急之时，大将军终于使出绝招，忽然间他全身散发金色闪光，你们知道那是什么？那可是传说中的“圣光气”。"},{"type":"say","who":"旅人","text":"邓艾见到大将军的实力，知道再有保留就老猫烧须了，当场运起“浑天宝鉴”心法。"},{"type":"say","who":"姜维","text":"他到底在说什么呀…蝴﹑ㄓ"},{"type":"say","who":"诸葛果","text":"和主公相约，果不敢迟到。"},{"type":"say","who":"诸葛果","text":"只是…主公真的要放任那个人胡说八道？如果允许的话，果可以…"},{"type":"say","who":"姜维","text":"没关系，这样乱讲反而比较好，至少不会有人真的把它当真。"},{"type":"say","who":"诸葛果","text":"主公害怕成为英雄的想法固然很好，但也请不要太执著。"},{"type":"say","who":"诸葛果","text":"如果世人认为您是真正的英雄，那么不管怎么隐瞒，到最后还是会被重新评价。"},{"type":"say","who":"姜维","text":"你太会夸奖人了。"},{"type":"say","who":"诸葛果","text":"果只是实话实说而已。"},{"type":"say","who":"姜维","text":"走吧，在路上你可以交代一下这一年到底做了些什么。传说的英雄天水冀城"},{"type":"say","who":"旅人","text":"大家都知道，咱们冀城出了个了不起的英雄，那个人就是姜维大将军。"},{"type":"say","who":"学者","text":"嗯…他真的是英雄吗？如果真要是的话，怎么会在最后平乱时死得那么突兀？"},{"type":"say","who":"旅人","text":"这可是有重重内幕，知道这件事的，只有三个人，一个是现任大司马，一个是我，另一个不能说。"},{"type":"say","who":"学者","text":"友滑兄，鬼扯也有个限度好吗？"},{"type":"say","who":"旅人","text":"外地人愚蠢，难道我们这些家乡父老也要跟著蠢吗？"},{"type":"say","who":"旅人","text":"我可以很大胆跟各位表示，姜维大将军是为了避免底下人拥护他当皇帝才诈死。"},{"type":"say","who":"女子","text":"哦？诈死？"},{"type":"say","who":"男子","text":"这个看法有点创意。"},{"type":"say","who":"旅人","text":"别看我这样，当年我可跟过大将军南征北讨，他的英雄风范可是一直看在眼里。"},{"type":"say","who":"旅人","text":"当时我是常败军的一员，曾经有一次和邓艾打仗的时候，被邓艾带兵追杀。"},{"type":"say","who":"文官","text":"你太扯淡了吧，邓艾追杀你这小兵？"},{"type":"say","who":"旅人","text":"话可不是这样说，邓艾这老贼残忍狡猾，连个小兵都不肯放过。"},{"type":"say","who":"旅人","text":"言归正传，正当危急之时，大将军忽然从旁杀出，挥动手中长枪，一枪就撂倒一个人，最后和邓艾打起来。"},{"type":"say","who":"旅人","text":"哪知邓艾那小人，居然叫弓弩手对大将军射击，结果你们知道怎么样吗？"},{"type":"say","who":"武官","text":"大将军逃跑？"},{"type":"say","who":"旅人","text":"错，大将军不慌不忙，勇敢地挥动手中长枪挡住那漫天飞箭，数万支箭居然都无法伤他分毫。"},{"type":"say","who":"旅人","text":"而更感人的是，他居然为了保护那时候受伤的我而寸步不移。"},{"type":"say","who":"姜维","text":"太夸张了，邓艾从来没带过那么多弓弩手吧。"},{"type":"say","who":"旅人","text":"老伯安静点，人家贼人随时都能聚兵百万，几万弓弩手不过是小意思。"},{"type":"say","who":"姜维","text":"抱歉，那最后大将军怎么样了？"},{"type":"say","who":"旅人","text":"都是你在那边乱说话，让精彩的故事被打断了。"},{"type":"say","who":"旅人","text":"正当危急之时，大将军终于使出绝招，忽然间他全身散发金色闪光，你们知道那是什么？那可是传说中的“圣光气”。"},{"type":"say","who":"旅人","text":"邓艾见到大将军的实力，知道再有保留就老猫烧须了，当场运起“浑天宝鉴”心法。"},{"type":"say","who":"姜维","text":"他到底在说什么呀…"},{"type":"say","who":"姜维","text":"咦？"},{"type":"say","who":"曹绫","text":"别小看曹家的情报能力，就算你躲到海外我都能把你抓出来。"},{"type":"say","who":"姜维","text":"本来想要在这里隐姓埋名过一辈子，看来这梦想还真没那么容易实现。"},{"type":"say","who":"曹绫","text":"你以为我是为了魏国来找你？不用担心，现在的魏国根本用不著你。"},{"type":"say","who":"姜维","text":"虽然让人放心，但你说话还真不留情。"},{"type":"say","who":"曹绫","text":"如果说，我是以曹绫这个女人的身份来找你，你会怎么反应？"},{"type":"say","who":"姜维","text":"该怎么反应呢？说实话可考倒我了。"},{"type":"say","who":"曹绫","text":"跟我来吧，在路上可以给你足够的时间来思考。三人的决定冀城姜家"},{"type":"say","who":"姜维","text":"本来以为可以躲在这地方不被人发现，没想到还是被你们找到了。"},{"type":"say","who":"杨兰","text":"好像还挺不甘愿…"},{"type":"say","who":"曹绫","text":"别小看我们的情报能力，要找到你并不是什么难事。"},{"type":"say","who":"姜维","text":"杨兰和诸葛果找我还能理解，为什么连公主都跑来？"},{"type":"say","who":"曹绫","text":"你真的不清楚？"},{"type":"say","who":"杨兰","text":"越来越让人生气了。"},{"type":"say","who":"诸葛果","text":"主公在战后就忽然诈死消失，让身边许多人都无所适从。"},{"type":"say","who":"诸葛果","text":"主公这样的作为虽然有所考量，但是却没考虑到被留下的人的心情。"},{"type":"say","who":"姜维","text":"（诸葛果似乎真的生气了，她生气的样子真恐怖。比起来，邓艾或文鸯都只是小意思而已。）"},{"type":"say","who":"姜维","text":"真的很对不起，当时我脑袋只能想到这样的烂主意…实在是情况太急迫了。"},{"type":"say","who":"曹绫","text":"其实呢，我先要跟你说一件事…"},{"type":"say","who":"曹绫","text":"这段时间我一直在思考自己的事，究竟我想要什么样的未来。"},{"type":"say","who":"姜维","text":"这也难怪，过去这将近二十年的时间，你几乎都在为曹家的存续奋斗，根本没有时间思考自己的事。"},{"type":"say","who":"曹绫","text":"想知道我在想什么事吗？"},{"type":"say","who":"姜维","text":"可以告诉我吗？"},{"type":"say","who":"曹绫","text":"母亲在我小的时候就遇害了，但在印象中，她个个性温厚，总是在迷迷糊糊过日子，是个没有人会讨厌她的好人。"},{"type":"say","who":"曹绫","text":"但是呢，在之前和辛宪英见面时，她居然跟我说了母亲的另外一面。"},{"type":"say","who":"曹绫","text":"她原来对自己的感情非常执著，她嫁给那害死她的父皇并不是被强迫的。"},{"type":"say","who":"曹绫","text":"我可以体会李明当年不告诉我这件事情的原因，因为她比谁爱母亲，根本无法原谅做出那种事的父皇。"},{"type":"say","who":"曹绫","text":"嗯…我要说的是…那个…其实…我虽然个性上有许多部份和母亲不太像，但或许在这一点上很像。"},{"type":"say","who":"曹绫","text":"我想了很久…也问了自己很久…或许我觉得将来能够在你身边是种不错的选择…"},{"type":"say","who":"姜维","text":"咦？"},{"type":"say","who":"杨兰","text":"真不知道你怎么会运气这么好，连这位魏国公主都看上你了。"},{"type":"say","who":"诸葛果","text":"相信她一定能成为主公的好内助。"},{"type":"say","who":"姜维","text":"等等，你们应该知道关于香的事情…"},{"type":"say","who":"曹绫","text":"没有关系，都到了这个年纪，早就不计较什么名份。"},{"type":"say","who":"杨兰","text":"尹香就当你永远的正妻，我们只要能够陪伴在你身边就够了。"},{"type":"say","who":"诸葛果","text":"请别在意果，不管是当仆人或是奴隶，果都愿为主公服务。"},{"type":"say","who":"姜维","text":"我该怎么说你们呢…"},{"type":"say","who":"曹绫","text":"你认为自己有选择的权力？伯母那边早就已经欣然同意了，难道你这抛弃母亲多年的不孝子还想要再不孝一次？"},{"type":"say","who":"姜维","text":"真是伤脑筋…久别的重逢冀城附近"},{"type":"say","who":"杨兰","text":"原来如此，伯母在这一年已经过世了…"},{"type":"say","who":"姜维","text":"不用太难过，毕竟已经算是享了天寿。能够在她人生最后一刻待在她身边，我也觉得没有遗憾了。"},{"type":"say","who":"姜维","text":"你这一年过得应该很轰轰烈烈吧…仇池一战的名声可是响彻天下。"},{"type":"say","who":"杨兰","text":"哈哈哈，想低调都不行。"},{"type":"say","who":"杨兰","text":"我的想法很简单，与其一直忍耐，然后到最后爆发仇杀，倒不如现在就一直进行小规模战争。"},{"type":"say","who":"杨兰","text":"透过这样的战争，也可以有效消化掉那些过剩的战力，避免制造问题。"},{"type":"say","who":"姜维","text":"不错的想法，现在太平之世最大的障碍，就是那些因为没有战争而失去工作的士兵。"},{"type":"say","who":"姜维","text":"虽说可以让士兵们回归农耕，但短时间内释放大量人力，只会造成耕地短缺。"},{"type":"say","who":"杨兰","text":"总之事情就是这样，先别管我的事了。现在是要问你的决定。"},{"type":"say","who":"杨兰","text":"既然当初跟我约好一年后在这里相见，应该就不会只是这样说几句话吧。"},{"type":"say","who":"姜维","text":"记得你当年对我说过的那些话吗？"},{"type":"say","who":"杨兰","text":"当然记得。"},{"type":"say","who":"姜维","text":"你说一直在等著我的回应，只是…"},{"type":"say","who":"旁白","text":"▶ 不需要了。"},{"type":"say","who":"姜维","text":"咦？"},{"type":"say","who":"杨兰","text":"都已经到了这个年纪，还会在乎那外在的无聊形式？妻子的角色就永远留给尹香就好了。"},{"type":"say","who":"杨兰","text":"只是你愿意将剩下的人生交给我吗？"},{"type":"say","who":"姜维","text":"这怎么比较像是我该问你的话？"},{"type":"say","who":"杨兰","text":"你当我会给你机会说吗？"},{"type":"say","who":"姜维","text":"哈哈哈，这些年来我面对郭淮也好，陈泰也好，陆抗也好，甚至是司马昭或是邓艾，都没有一定会输给他们的感觉。"},{"type":"say","who":"姜维","text":"只有面对你我觉得一点胜算也没有。"},{"type":"say","who":"姜维","text":"如何？仇池国还有我的位子吗？"},{"type":"say","who":"杨兰","text":"我还以为你会要我跟你回冀城…"},{"type":"say","who":"姜维","text":"现在留在冀城的只剩下回忆，如果一直停留在这里，相信娘和香也不愿意看见。"},{"type":"say","who":"姜维","text":"虽说迟了点，但我还是希望能用剩余的人生来向前迈进。"},{"type":"say","who":"杨兰","text":"就等著你这句话，我们仇池国欢迎你。久别的重逢冀城附近"},{"type":"say","who":"诸葛果","text":"没想到主公的母亲居然在这一年过世了…"},{"type":"say","who":"姜维","text":"不用太难过，毕竟已经算是享了天寿。能够在她人生最后一刻待在她身边，我也觉得没有遗憾了。"},{"type":"say","who":"姜维","text":"你这一年应该都待在思远的府中吧，我猜他不管做什么事情都离不开你。"},{"type":"say","who":"诸葛果","text":"主公果然睿智。小瞻虽然已经颇有才干，但目前还是缺乏信心。"},{"type":"say","who":"诸葛果","text":"其实果目前也只是在引导他，让小瞻慢慢建立起自己的信心而已。"},{"type":"say","who":"姜维","text":"思远是我看重能够领导下个世代的人。"},{"type":"say","who":"姜维","text":"他年轻，有良好品德和崇高的声誉。比起我这样毁誉参半的人，他更是适合领导大汉。"},{"type":"say","who":"诸葛果","text":"不对，主公是自愿背负起一切污名才会变成这样，您要是愿意，现在绝对还是大汉不可动摇的英雄。"},{"type":"say","who":"姜维","text":"幼常以为自己能够背负所有污名，把我拱成英雄，消灭陛下势力就会天下太平。"},{"type":"say","who":"姜维","text":"但是他错了，这样只会制造下一个董卓或曹操，这个回圈终究没有结束。"},{"type":"say","who":"姜维","text":"我掌握的权力太大，名声也太高，根本就无人能够制衡我。"},{"type":"say","who":"姜维","text":"相对来说，思远虽然有美名，但他的实力终究是不足…抱歉，一不小心就多说了。"},{"type":"say","who":"诸葛果","text":"主公说得很对，今后不需要强人，也不需要英雄，今后应该是建立一个需要所有平凡人齐心才能维持下去的天下。"},{"type":"say","who":"姜维","text":"嗯…听起来很梦幻，但我们确实在一步步让它实现。"},{"type":"say","who":"姜维","text":"有件事情我想跟你说…"},{"type":"say","who":"旁白","text":"▶ 不需要了。"},{"type":"say","who":"姜维","text":"咦？我明明还没开口…"},{"type":"say","who":"诸葛果","text":"主公不会无端要果在一年之后前来冀城，想来想去也只有一种可能。"},{"type":"say","who":"诸葛果","text":"果这些年陪在主公身边，要的绝对不是这个。"},{"type":"say","who":"诸葛果","text":"而是这伴随的过程就已经让果觉得很快乐了。"},{"type":"say","who":"诸葛果","text":"觉得很不可思议吗？但人其实就是一种需要感受到被他人需要的生物，果只是顺应的这种本能生活著而已。"},{"type":"say","who":"姜维","text":"这种固执劲究竟像谁呢？"},{"type":"say","who":"诸葛果","text":"这就是诸葛果这个女人的本性。"},{"type":"say","who":"姜维","text":"那么…诸葛家还有我的位子吗？"},{"type":"say","who":"诸葛果","text":"还以为主公会要果跟您回冀城…"},{"type":"say","who":"姜维","text":"现在留在冀城的只剩下回忆，如果一直停留在这里，相信娘和香也不愿意看见。"},{"type":"say","who":"姜维","text":"虽说迟了点，但我还是希望能用剩余的人生来向前迈进。"},{"type":"say","who":"诸葛果","text":"果明白了，请主公跟随果前往吧。久别的重逢冀城附近"},{"type":"say","who":"曹绫","text":"没想到伯母居然在这一年过世了…"},{"type":"say","who":"姜维","text":"不用太难过，毕竟已经算是享了天寿。能够在她人生最后一刻待在她身边，我也觉得没有遗憾了。"},{"type":"say","who":"姜维","text":"你这段日子在做什么？扶持曹芳？还是回去谯郡故里？"},{"type":"say","who":"曹绫","text":"应该说我什么都没做，只是在整理一下思绪而已。"},{"type":"say","who":"姜维","text":"这也难怪，过去这将近二十年的时间，你几乎都在为曹家的存续奋斗，根本没有时间思考自己的事。"},{"type":"say","who":"曹绫","text":"想知道我在想什么事吗？"},{"type":"say","who":"姜维","text":"可以告诉我吗？"},{"type":"say","who":"曹绫","text":"母亲在我小的时候就遇害了，但在印象中，她个个性温厚，总是在迷迷糊糊过日子，是个没有人会讨厌她的好人。"},{"type":"say","who":"曹绫","text":"但是呢，在之前和辛宪英见面时，她居然跟我说了母亲的另外一面。"},{"type":"say","who":"曹绫","text":"她原来对自己的感情非常执著，她嫁给那害死她的父皇并不是被强迫的。"},{"type":"say","who":"曹绫","text":"我可以体会李明当年不告诉我这件事情的原因，因为她比谁爱母亲，根本无法原谅做出那种事的父皇。"},{"type":"say","who":"曹绫","text":"嗯…我要说的是…那个…其实…我虽然个性上有许多部份和母亲不太像，但或许在这一点上很像。"},{"type":"say","who":"曹绫","text":"我想了很久…也问了自己很久…或许我觉得将来能够在你身边是种不错的选择…"},{"type":"say","who":"姜维","text":"你也应该知道香…"},{"type":"say","who":"曹绫","text":"没有关系的，都已经到了这个年纪，还会再在意名份就太愚蠢了。尹香本来就应该"},{"type":"say","who":"旁白","text":"▶ 是你永远的妻子。"},{"type":"say","who":"姜维","text":"你在邺城那边还有地方容纳我？"},{"type":"say","who":"曹绫","text":"咦？还以为会要我跟你回冀城…"},{"type":"say","who":"姜维","text":"现在留在冀城的只剩下回忆，如果一直停留在这里，相信娘和香也不愿意看见。"},{"type":"say","who":"姜维","text":"虽说迟了点，但我还是希望能用剩余的人生来向前迈进。"},{"type":"say","who":"曹绫","text":"原来如此，那么就跟著我走吧。或许我们还可以绕路前去朝阳陵看看。"},{"type":"say","who":"姜维","text":"朝阳陵？好熟的名字。"},{"type":"say","who":"曹绫","text":"之前你看过皇兄的高平陵，现在是该让你看看母后的朝阳陵，相信她会很乐意见到你的。"},{"type":"say","who":"姜维","text":"（这种表情丰富，言谈流畅开朗的样子，或许才是曹绫真正的面貌吧。）"},{"type":"say","who":"姜维","text":"（看来我的一念之间不但帮她卸下了复兴魏国的重担，也解放了她的内心。这样的结果是再好不过的。）永远的两人仇池外族营帐氐族兵报告，刚才汉军已经被我们击退，现在危机解除了。"},{"type":"say","who":"杨兰","text":"很好，就说只要听我们的，再多汉军来也是送死而已。氐族兵义母果然神勇无比，义父您的用兵更是让人敬佩。氐族兵只是…到现在还不知道您叫什么名字…"},{"type":"say","who":"姜维","text":"那一点也不重要，你还是跟著杨兰姓好了，杨飞龙这名字真的挺响亮的。氐族兵嘿嘿，说得也是。其实我最近还编了一首战歌，到时打仗时唱一定能提振士气。氐族兵手牵手，心逗阵。把握好时机，亲像飞龙飞上天。"},{"type":"say","who":"杨兰","text":"你先下去吧，这歌听得我头好痛…氐族兵义母呀，我发现您只要在义父身边，用词就变得文雅许多。"},{"type":"say","who":"杨兰","text":"废话这么多干嘛，还不快去准备战斗。氐族兵…是…"},{"type":"say","who":"姜维","text":"这里朝气蓬勃，真是个好地方。"},{"type":"say","who":"杨兰","text":"一年多前可不是这样，当时这些失去领袖的外族部众，背负著起兵造反的罪名，一路上遭遇汉人攻击。"},{"type":"say","who":"杨兰","text":"不管有参加过战斗的还是没参加过战斗的，几乎都受到毁灭性的打击。"},{"type":"say","who":"姜维","text":"我记得齐万年那家伙似乎就期望看见这种景象，他根本不把自己族人生命当回事。"},{"type":"say","who":"杨兰","text":"那些人也真是倒楣，自己族里有堆疯子，还被外面那些野心家利用。"},{"type":"say","who":"姜维","text":"幼常早就预见到会这样，但他还是选择去做，他的罪孽绝对不轻。"},{"type":"say","who":"姜维","text":"所以我得感谢你，如果不是你拯救这些人，我和幼常的罪孽将深重到无以复加。"},{"type":"say","who":"杨兰","text":"还是老样子呀，提到别人的事情就热中得不得了。"},{"type":"say","who":"杨兰","text":"对自己倒是毫不关心。"},{"type":"say","who":"姜维","text":"毕竟我还是不习惯没人依赖我的生活，总觉得忽然失去重心一样。"},{"type":"say","who":"杨兰","text":"可怜的被虐狂，难怪当年尹香要加给你这么多枷锁，要不然你恐怕活不到现在。"},{"type":"say","who":"杨兰","text":"不管怎么说，你还是要学会放下。你不是说过吗？天下不需要英雄，而是要大家互相扶持走下去。"},{"type":"say","who":"姜维","text":"哈哈哈，我又忘记自己说过的话，该不会真的是年纪大了？"},{"type":"say","who":"杨兰","text":"别担心，要是真的老人失智，也会有个永远的十七岁陪著你。"},{"type":"say","who":"姜维","text":"咦？"},{"type":"say","who":"宁随","text":"………"},{"type":"say","who":"尹香","text":"………"},{"type":"say","who":"诸葛亮","text":"………"},{"type":"say","who":"杨兰","text":"怎么了吗？"},{"type":"say","who":"姜维","text":"没什么…"},{"type":"say","who":"姜维","text":"（谢谢…因为你们，我的一生过得精采无比。）永远的两人雒阳大司马府"},{"type":"say","who":"黄月英","text":"真没想到伯约你最后还是进了我们家。"},{"type":"say","who":"诸葛果","text":"娘，主公并没有进我们家…"},{"type":"say","who":"黄月英","text":"呵呵呵…没关系，娘知道自己女儿的想法。"},{"type":"say","who":"黄月英","text":"伯约，请把这里当作是自己家，如果可以的话，也希望你把我当作是自己娘亲来看待。"},{"type":"say","who":"姜维","text":"多谢丞相夫人的好意。"},{"type":"say","who":"黄月英","text":"这就不打扰你们，我还要去和瞻儿沟通一下，他已经气了足足三天，这孩子真是永远都长不大。"},{"type":"say","who":"姜维","text":"看见诸葛家能够这么壮盛，真的感到相当欣慰。"},{"type":"say","who":"姜维","text":"本来我一直在想，把事情都托付给思远是不是正确的决定。"},{"type":"say","who":"诸葛果","text":"主公不用担心，小瞻他只要建立起自信，很多事情都能慢慢上轨道。"},{"type":"say","who":"诸葛果","text":"更何况他身边还有许多人帮忙，不会有问题的。"},{"type":"say","who":"姜维","text":"这样就好，如果思远还需要帮忙的话，我也随时都可以…"},{"type":"say","who":"诸葛果","text":"不行！"},{"type":"say","who":"姜维","text":"咦？"},{"type":"say","who":"诸葛果","text":"抱歉，但是主公忘记自己曾经说过的话？"},{"type":"say","who":"诸葛果","text":"今后不需要强人，也不需要英雄，今后应该是建立一个需要所有平凡人齐心才能维持下去的天下。"},{"type":"say","who":"姜维","text":"你说得对，要是我再参入，到时搞不好就脱不了身，也只会让思远的立场越来越尴尬而已。"},{"type":"say","who":"姜维","text":"话说回来，我发现你的个性其实还挺强悍的，和我当初的印象感觉差很多。"},{"type":"say","who":"诸葛果","text":"如果主公希望的话，果也可以改正…只是…这是果的本性，也请主公明白。"},{"type":"say","who":"姜维","text":"不用担心，我就一直在想你是哪里像丞相，直到现在我才明白，那颗强韧的心就是遗传自丞相最好的证明。"},{"type":"say","who":"姜维","text":"今后你就照著自己的想法来面对我吧，这样或许对你我都比较轻松。"},{"type":"say","who":"旁白","text":"▶ 是的，主公。"},{"type":"say","who":"姜维","text":"你果然还是很固执呀…"},{"type":"say","who":"姜维","text":"咦？"},{"type":"say","who":"宁随","text":"………"},{"type":"say","who":"尹香","text":"………"},{"type":"say","who":"诸葛亮","text":"………"},{"type":"say","who":"诸葛果","text":"怎么了吗？"},{"type":"say","who":"姜维","text":"没什么…"},{"type":"say","who":"姜维","text":"（谢谢…因为你们，我的一生过得精采无比。）永远的两人邺城东乡公主宅邸"},{"type":"say","who":"曹芳","text":"姑母，您什么时候回到邺城？怎么也不让侄儿迎接您。"},{"type":"say","who":"曹绫","text":"毕竟我们也不是什么重要人物，实在不需要麻烦你。"},{"type":"say","who":"曹芳","text":"可是…就算扣除掉姑母，姜伯约大将军也是我们魏国的恩人，怎么可以怠慢？"},{"type":"say","who":"姜维","text":"魏王别这样说，魏国能够再兴靠的是各位魏臣和曹氏家族成员的齐心合作，和姜维一点关系也没有。"},{"type":"say","who":"曹绫","text":"今后侄儿你也尽量不要往这里跑，否则要是这里成为魏国的影子政府就糟了。"},{"type":"say","who":"曹芳","text":"可是侄儿今后还有很多问题…"},{"type":"say","who":"曹绫","text":"那你应该去找陈泰、鲁芝或是夏侯霸，一国的统治者应该有这样的判断能力。"},{"type":"say","who":"曹绫","text":"不用担心，目前你做得很好，皇兄把大魏托付你绝对没有错。"},{"type":"say","who":"曹绫","text":"多相信自己一点，魏国会越来越好的。"},{"type":"say","who":"曹芳","text":"那么侄儿告退了，多谢姑母您的一番话。"},{"type":"say","who":"曹绫","text":"这样就行了，总不能让侄儿他一直依赖我。"},{"type":"say","who":"姜维","text":"这样的选择很正确，现在依靠一个人撑起一个国家或天下的时代已经过去，接下来应该是群策群力的新时代。"},{"type":"say","who":"曹绫","text":"话说得很大，真的有办法实现吗？"},{"type":"say","who":"姜维","text":"为了达成这个目标，我们已经付出太重大的牺牲，非得实现不可。"},{"type":"say","who":"曹绫","text":"嗯…这个话题就到此为止吧。"},{"type":"say","who":"曹绫","text":"我花了很多时间才弄清楚自己的想法，想要跟你度过余生。"},{"type":"say","who":"曹绫","text":"说实话我觉得自己很幸运，我们曹家女子能够凭著自己意志来决定归属的，恐怕我是第一个。"},{"type":"say","who":"曹绫","text":"不管是清河长公主、金阳公主或是献穆皇后，大家都是被迫和自己不认识的人成婚。"},{"type":"say","who":"姜维","text":"结果你以自己的意志决定是我？"},{"type":"say","who":"曹绫","text":"觉得很不可思议吗？因为我们见面的次数寥寥可数，远不如你身边的两个女人？"},{"type":"say","who":"曹绫","text":"不，这一点也不重要。"},{"type":"say","who":"曹绫","text":"只要当我问起自己，最希望陪在身边的是谁，而最后浮现的人就是你时，这样就够了。"},{"type":"say","who":"姜维","text":"说得也是，时间的长短并不是最重要的，而是内心的感觉。"},{"type":"say","who":"姜维","text":"咦？"},{"type":"say","who":"宁随","text":"………"},{"type":"say","who":"尹香","text":"………"},{"type":"say","who":"诸葛亮","text":"………"},{"type":"say","who":"曹绫","text":"怎么了吗？"},{"type":"say","who":"姜维","text":"没什么…"},{"type":"say","who":"姜维","text":"（放心过这样的生活就好，是吗？）"},{"type":"say","who":"姜维","text":"（谢谢…因为你们，我的一生过得精采无比。）永远的羁绊尹香墓前"},{"type":"say","who":"姜维","text":"香，请你谅解。就算不是奉母亲之命，我内心也倾向有人能够扶持我走完剩下的人生。"},{"type":"say","who":"姜维","text":"不过你是我妻子这件事情是永远不会改变的。感谢你在我人生最低潮时帮助我走过来。"},{"type":"say","who":"杨兰","text":"结束了？"},{"type":"say","who":"姜维","text":"嗯，这样就好。要是一直沉浸在过去，恐怕将永远无法向未来迈进。"},{"type":"say","who":"曹绫","text":"接下来有件很重要的事。"},{"type":"say","who":"杨兰","text":"我们三人虽然决定同时陪伴你，但还是要分个次序高低。"},{"type":"say","who":"诸葛果","text":"请主公不要在意果，只要专心搞定两位就行。"},{"type":"say","who":"曹绫","text":"论年纪，我略长于杨兰。论家世，我们曹家也是高门第的家族。"},{"type":"say","who":"曹绫","text":"所以我排在前面是理所当然的事。"},{"type":"say","who":"杨兰","text":"有道理，若比皱纹数的话还真是输你。"},{"type":"say","who":"曹绫","text":"哎呀，刚才那句话可不能当作没听到了。"},{"type":"say","who":"曹绫","text":"我们出身名门的人很清楚该怎么保养，不像某些只会在骑马跑来跑去的，皮肤都弄坏掉了。"},{"type":"say","who":"杨兰","text":"哼，真要说的话，我可是一直待在姜维身边，诸葛果也勉强说过去。"},{"type":"say","who":"杨兰","text":"而你呢？只是像个小偷一样，最后面才跑出来要分一杯羹，照先来先赢的道理，你应该是最小的。"},{"type":"say","who":"曹绫","text":"哦？那么我们问问看姜维怎么决定。"},{"type":"say","who":"姜维","text":"咦？"},{"type":"say","who":"曹绫","text":"怎么了吗？"},{"type":"say","who":"杨兰","text":"你在发什么呆？"},{"type":"say","who":"诸葛果","text":"主公似乎是看见了什么。"},{"type":"say","who":"姜维","text":"没什么…"},{"type":"say","who":"姜维","text":"（谢谢…因为你们，我的一生过得精采无比。）"},{"type":"battle","index":0}]},"battles":[{"index":0,"width":16,"height":10,"objective":"全灭敌军","grid":["ffffffffffffffff","ffffffffffffffff","ffppppppppppppff","fppppppppppppppf","fpwwwpppppwwwppf","fpwwpppppppwwppf","fpwwwpppppwwwppf","fppppppppppppppf","ffppppppppppppff","ffffffffffffffff"],"units":[{"def":{"name":"姜维","class":"commander","level":8,"skills":["fireball","heal","inspire"],"weapon":"sword","leader":true},"x":3,"y":4,"faction":"ally"},{"def":{"name":"赵云","class":"hero","level":9,"skills":["charge"],"weapon":"hualiu"},"x":4,"y":5,"faction":"ally"},{"def":{"name":"王平","class":"infantry","level":7,"skills":[],"weapon":"sword"},"x":3,"y":6,"faction":"ally"},{"def":{"name":"马岱","class":"dragoon","level":7,"skills":["charge"],"weapon":"halberd"},"x":5,"y":5,"faction":"ally"},{"def":{"name":"魏将","class":"officer","level":6,"skills":[],"weapon":"sword"},"x":11,"y":3,"faction":"enemy"},{"def":{"name":"魏将","class":"officer","level":6,"skills":[],"weapon":"sword"},"x":11,"y":7,"faction":"enemy"},{"def":{"name":"枪兵","class":"spearman","level":5,"skills":[],"weapon":"spear"},"x":10,"y":5,"faction":"enemy"},{"def":{"name":"弓兵","class":"archer","level":5,"skills":[],"weapon":"bow"},"x":13,"y":4,"faction":"enemy"}]}]});
})();
